import { useState } from "react";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Label } from "@/components/ui/label";
import { Wand2, Plus, X, BookOpen } from "lucide-react";
import { toast } from "sonner";
import { GoogleGenAI } from "@google/genai";
import { getStoredApiKey } from "@/utils/apiKeyUtils";
import type { Modulo } from "@/types/courseData";

interface CompletionModulesProps {
    modules: Modulo[];
    onUpdate?: (updatedModules: Modulo[]) => void;
}

export const CompletionModules = ({ modules, onUpdate }: CompletionModulesProps) => {
    const [newArg, setNewArg] = useState<string>("");
    const [generatingId, setGeneratingId] = useState<string | null>(null);
    const canEdit = Boolean(onUpdate);

    const handleAddArg = (moduleIndex: number) => {
        if (!newArg.trim() || !onUpdate) return;

        const updatedModules = [...modules];
        const currentArgs = updatedModules[moduleIndex].argomenti || [];
        updatedModules[moduleIndex] = {
            ...updatedModules[moduleIndex],
            argomenti: [...currentArgs, newArg.trim()]
        };

        onUpdate(updatedModules);
        setNewArg("");
    };

    const handleRemoveArg = (moduleIndex: number, argIndex: number) => {
        if (!onUpdate) return;

        const updatedModules = [...modules];
        const currentArgs = updatedModules[moduleIndex].argomenti || [];
        updatedModules[moduleIndex] = {
            ...updatedModules[moduleIndex],
            argomenti: currentArgs.filter((_, idx) => idx !== argIndex)
        };

        onUpdate(updatedModules);
    };

    const handleGenerateAI = async (moduleIndex: number, moduleTitle: string) => {
        if (!onUpdate) return;

        const apiKey = getStoredApiKey();
        if (!apiKey) {
            toast.error("API Key non trovata. Configurala nelle impostazioni.");
            return;
        }

        setGeneratingId(modules[moduleIndex].id);

        try {
            const genAI = new GoogleGenAI(apiKey);
            const model = genAI.getGenerativeModel({ model: 'gemini-2.0-flash' });

            const prompt = `Genera una lista di 5-7 argomenti didattici dettagliati per un modulo formativo intitolato "${moduleTitle}". 
            Gli argomenti devono essere brevi, concisi e professionali. 
            Restituisci SOLO la lista puntata, senza premesse o altro testo.`;

            const result = await model.generateContent({
                contents: [{ role: "user", parts: [{ text: prompt }] }]
            });

            const text = result.response.text() || "";

            const generatedArgs = text.split('\n')
                .map(line => line.replace(/^[•\-\*]\s*/, '').trim())
                .filter(line => line.length > 0);

            if (generatedArgs.length > 0) {
                const updatedModules = [...modules];
                const currentArgs = updatedModules[moduleIndex].argomenti || [];
                // Merge avoiding duplicates
                const newArgs = [...new Set([...currentArgs, ...generatedArgs])];

                updatedModules[moduleIndex] = {
                    ...updatedModules[moduleIndex],
                    argomenti: newArgs
                };

                onUpdate(updatedModules);
                toast.success("Argomenti generati con successo!");
            } else {
                toast.warning("Nessun argomento generato.");
            }
        } catch (error) {
            console.error("AI Generation error:", error);
            toast.error("Errore durante la generazione AI.");
        } finally {
            setGeneratingId(null);
        }
    };

    const handleModuleFieldChange = (moduleIndex: number, field: keyof Modulo, value: string) => {
        if (!onUpdate) return;
        const updatedModules = [...modules];
        updatedModules[moduleIndex] = {
            ...updatedModules[moduleIndex],
            [field]: value
        };
        onUpdate(updatedModules);
    };

    return (
        <AccordionItem value="moduli" className="border rounded-lg px-6">
            <AccordionTrigger className="hover:no-underline">
                <span className="text-lg font-semibold">📚 Moduli del Corso ({modules.length})</span>
            </AccordionTrigger>
            <AccordionContent className="space-y-4 pt-4">
                <Accordion type="single" collapsible className="w-full space-y-2">
                    {modules.map((modulo, idx) => (
                        <AccordionItem key={modulo.id} value={`modulo-${idx}`} className="border rounded-md">
                            <AccordionTrigger className="px-4 hover:no-underline">
                                <div className="flex items-center gap-3 flex-wrap">
                                    <span className="font-semibold">Modulo {idx + 1}</span>
                                    <span className="text-sm text-muted-foreground truncate max-w-[200px]">
                                        {modulo.titolo}
                                    </span>
                                    <span className="text-xs bg-primary/10 px-2 py-1 rounded">
                                        ID Corso: {modulo.id_corso}
                                    </span>
                                </div>
                            </AccordionTrigger>
                            <AccordionContent>
                                <div className="p-4 space-y-6">
                                    {/* Identificativi editabili */}
                                    <div className="grid grid-cols-1 md:grid-cols-3 gap-3 bg-muted/20 p-3 rounded-md">
                                        <div className="space-y-1">
                                            <Label htmlFor={`id-corso-${idx}`} className="text-xs font-semibold">
                                                ID Corso
                                            </Label>
                                            <Input
                                                id={`id-corso-${idx}`}
                                                value={modulo.id_corso}
                                                onChange={(e) => handleModuleFieldChange(idx, "id_corso", e.target.value)}
                                                disabled={!canEdit}
                                            />
                                        </div>
                                        <div className="space-y-1">
                                            <Label htmlFor={`id-sezione-${idx}`} className="text-xs font-semibold">
                                                ID Sezione
                                            </Label>
                                            <Input
                                                id={`id-sezione-${idx}`}
                                                value={modulo.id_sezione}
                                                onChange={(e) => handleModuleFieldChange(idx, "id_sezione", e.target.value)}
                                                disabled={!canEdit}
                                            />
                                        </div>
                                        <div className="space-y-1 md:col-span-1">
                                            <Label htmlFor={`titolo-${idx}`} className="text-xs font-semibold">
                                                Titolo Modulo
                                            </Label>
                                            <Input
                                                id={`titolo-${idx}`}
                                                value={modulo.titolo}
                                                onChange={(e) => handleModuleFieldChange(idx, "titolo", e.target.value)}
                                                disabled={!canEdit}
                                            />
                                        </div>
                                    </div>

                                    {/* Dati Generali */}
                                    <div className="grid grid-cols-2 gap-4 p-4 bg-muted/30 rounded-lg">
                                        <div>
                                            <p className="text-sm font-medium">Date</p>
                                            <p className="text-sm text-muted-foreground">
                                                {modulo.data_inizio} - {modulo.data_fine}
                                            </p>
                                        </div>
                                        <div>
                                            <p className="text-sm font-medium">Ore Totali</p>
                                            <p className="text-sm text-muted-foreground">{modulo.ore_totali}</p>
                                        </div>
                                        <div>
                                            <p className="text-sm font-medium">Sessioni</p>
                                            <p className="text-sm text-muted-foreground">
                                                {modulo.numero_sessioni} totali ({modulo.sessioni_presenza.length} in presenza)
                                            </p>
                                        </div>
                                        <div>
                                            <p className="text-sm font-medium">Stato</p>
                                            <p className="text-sm text-muted-foreground">{modulo.stato}</p>
                                        </div>
                                    </div>

                                    {/* Gestione Argomenti */}
                                    <div className="space-y-3">
                                        <div className="flex items-center justify-between">
                                            <h4 className="text-sm font-semibold flex items-center gap-2">
                                                <BookOpen className="h-4 w-4" />
                                                Argomenti Didattici
                                            </h4>
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                onClick={() => handleGenerateAI(idx, modulo.titolo)}
                                                disabled={generatingId === modulo.id || !onUpdate}
                                            >
                                                <Wand2 className={`mr-2 h-3 w-3 ${generatingId === modulo.id ? 'animate-spin' : ''}`} />
                                                {generatingId === modulo.id ? 'Generazione...' : 'Genera con AI'}
                                            </Button>
                                        </div>

                                        <div className="flex gap-2">
                                            <Input
                                                placeholder="Aggiungi argomento manualmente..."
                                                value={newArg}
                                                onChange={(e) => setNewArg(e.target.value)}
                                                onKeyDown={(e) => {
                                                    if (e.key === 'Enter') {
                                                        e.preventDefault();
                                                        handleAddArg(idx);
                                                    }
                                                }}
                                                disabled={!onUpdate}
                                            />
                                            <Button size="icon" onClick={() => handleAddArg(idx)} disabled={!onUpdate}>
                                                <Plus className="h-4 w-4" />
                                            </Button>
                                        </div>

                                        <div className="flex flex-wrap gap-2 min-h-[50px] p-3 bg-accent/5 rounded-lg border border-dashed">
                                            {(modulo.argomenti && modulo.argomenti.length > 0) ? (
                                                modulo.argomenti.map((arg, argIdx) => (
                                                    <Badge key={argIdx} variant="secondary" className="pl-2 pr-1 py-1 flex items-center gap-1">
                                                        {arg}
                                                        {onUpdate && (
                                                            <button
                                                                onClick={() => handleRemoveArg(idx, argIdx)}
                                                                className="hover:bg-destructive/20 rounded-full p-0.5 transition-colors"
                                                            >
                                                                <X className="h-3 w-3" />
                                                            </button>
                                                        )}
                                                    </Badge>
                                                ))
                                            ) : (
                                                <span className="text-sm text-muted-foreground italic w-full text-center py-2">
                                                    Nessun argomento inserito. Usa l'AI o aggiungili manualmente.
                                                </span>
                                            )}
                                        </div>
                                    </div>

                                    {/* Lista sessioni del modulo */}
                                    <div>
                                        <p className="text-sm font-semibold mb-2">Dettaglio Sessioni:</p>
                                        <div className="space-y-1 max-h-48 overflow-y-auto border rounded-md p-2">
                                            {modulo.sessioni.map((sess, sIdx) => (
                                                <div key={sIdx} className="text-xs p-2 hover:bg-accent/50 rounded flex justify-between items-center">
                                                    <span className="font-medium">{sess.data_completa}</span>
                                                    <span className="text-muted-foreground">{sess.ora_inizio_giornata} - {sess.ora_fine_giornata}</span>
                                                    <span className={`px-2 py-0.5 rounded text-xs font-medium ${sess.is_fad ? "bg-blue-100 text-blue-700" : "bg-green-100 text-green-700"
                                                        }`}>
                                                        {sess.is_fad ? "FAD" : "Presenza"}
                                                    </span>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                </div>
                            </AccordionContent>
                        </AccordionItem>
                    ))}
                </Accordion>
            </AccordionContent>
        </AccordionItem>
    );
};

/**
 * Folder Structure Settings Component
 *
 * Purpose: Allows users to configure ZIP folder structure
 * - Reorder folders
 * - Enable/disable folders
 * - Rename folders
 * - Configure ZIP generation options
 */

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import {
  FolderOpen,
  GripVertical,
  Trash2,
  Plus,
  Save,
  RotateCcw,
} from 'lucide-react';
import { toast } from 'sonner';
import type { FolderDefinition, FolderStructureSettings } from '@/types/userSettings';
import { DEFAULT_FOLDER_STRUCTURE } from '@/types/userSettings';
import { SYSTEM_TEMPLATES } from '@/services/templateRegistry';
import { Checkbox } from '@/components/ui/checkbox';
import { ScrollArea } from '@/components/ui/scroll-area';

interface TemplateOption {
  id: string;
  name: string;
  type: 'system' | 'local' | 'db';
}

// ============================================================================
// STORAGE HELPERS
// ============================================================================

const STORAGE_KEY = 'folderStructureSettings';

function loadSettings(): FolderStructureSettings {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored) {
      return JSON.parse(stored);
    }
  } catch (error) {
    console.error('Error loading folder structure settings:', error);
  }
  return DEFAULT_FOLDER_STRUCTURE;
}

function saveSettings(settings: FolderStructureSettings): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch (error) {
    console.error('Error saving folder structure settings:', error);
    throw error;
  }
}

// ============================================================================
// COMPONENT
// ============================================================================

const FolderStructureSettings = () => {
  const [settings, setSettings] = useState<FolderStructureSettings>(loadSettings());
  const [hasChanges, setHasChanges] = useState(false);
  const [availableTemplates, setAvailableTemplates] = useState<TemplateOption[]>([]);

  // Load available templates
  useEffect(() => {
    const loadTemplates = async () => {
      const options: TemplateOption[] = [];

      // 1. System Templates
      Object.values(SYSTEM_TEMPLATES).forEach(t => {
        options.push({ id: t.id, name: t.name, type: 'system' });
      });

      // 2. Local Templates
      try {
        const response = await fetch('/templates/manifest.json');
        if (response.ok) {
          const manifest = await response.json();
          if (manifest.templates) {
            manifest.templates.forEach((t: any) => {
              options.push({ id: t.id, name: t.name, type: 'local' });
            });
          }
        }
      } catch (e) {
        console.error("Failed to load local templates", e);
      }

      setAvailableTemplates(options);
    };

    loadTemplates();
  }, []);

  // Track changes
  useEffect(() => {
    const current = JSON.stringify(settings);
    const stored = JSON.stringify(loadSettings());
    setHasChanges(current !== stored);
  }, [settings]);

  /**
   * Saves settings to localStorage
   */
  const handleSave = () => {
    try {
      saveSettings(settings);
      toast.success('Impostazioni salvate!');
      setHasChanges(false);
    } catch (error) {
      toast.error('Errore durante il salvataggio');
    }
  };

  /**
   * Resets to default settings
   */
  const handleReset = () => {
    setSettings(DEFAULT_FOLDER_STRUCTURE);
    toast.info('Impostazioni ripristinate ai valori predefiniti');
  };

  /**
   * Toggles folder enabled state
   */
  const toggleFolder = (folderId: string) => {
    setSettings((prev) => ({
      ...prev,
      folders: prev.folders.map((f) =>
        f.id === folderId ? { ...f, enabled: !f.enabled } : f
      ),
    }));
  };

  /**
   * Updates folder name
   */
  const updateFolderName = (folderId: string, name: string) => {
    setSettings((prev) => ({
      ...prev,
      folders: prev.folders.map((f) =>
        f.id === folderId ? { ...f, name } : f
      ),
    }));
  };

  /**
   * Moves folder up in order
   */
  const moveFolderUp = (folderId: string) => {
    setSettings((prev) => {
      const folders = [...prev.folders];
      const index = folders.findIndex((f) => f.id === folderId);
      if (index > 0) {
        [folders[index - 1], folders[index]] = [folders[index], folders[index - 1]];
        // Update order numbers
        folders.forEach((f, i) => {
          f.order = i + 1;
        });
      }
      return { ...prev, folders };
    });
  };

  /**
   * Moves folder down in order
   */
  const moveFolderDown = (folderId: string) => {
    setSettings((prev) => {
      const folders = [...prev.folders];
      const index = folders.findIndex((f) => f.id === folderId);
      if (index < folders.length - 1) {
        [folders[index], folders[index + 1]] = [folders[index + 1], folders[index]];
        // Update order numbers
        folders.forEach((f, i) => {
          f.order = i + 1;
        });
      }
      return { ...prev, folders };
    });
  };

  /**
   * Removes a folder
   */
  const removeFolder = (folderId: string) => {
    setSettings((prev) => ({
      ...prev,
      folders: prev.folders.filter((f) => f.id !== folderId),
    }));
    toast.success('Cartella rimossa');
  };

  /**
   * Adds a new folder
   */
  const addFolder = () => {
    const newFolder: FolderDefinition = {
      id: `folder_${Date.now()}`,
      name: 'Nuova Cartella',
      order: settings.folders.length + 1,
      enabled: true,
      fileTypes: [],
      icon: '📁',
    };

    setSettings((prev) => ({
      ...prev,
      folders: [...prev.folders, newFolder],
    }));

    toast.success('Nuova cartella aggiunta');
  };

  /**
   * Toggles a template assignment for a folder
   */
  const toggleTemplateAssignment = (folderId: string, templateId: string) => {
    setSettings((prev) => ({
      ...prev,
      folders: prev.folders.map((f) => {
        if (f.id !== folderId) return f;

        const currentAssigned = f.assignedTemplates || [];
        const isAssigned = currentAssigned.includes(templateId);

        let newAssigned;
        if (isAssigned) {
          newAssigned = currentAssigned.filter(id => id !== templateId);
        } else {
          newAssigned = [...currentAssigned, templateId];
        }

        return { ...f, assignedTemplates: newAssigned };
      }),
    }));
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <Card className="p-6">
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <h3 className="text-lg font-semibold flex items-center gap-2">
              <FolderOpen className="h-5 w-5 text-primary" />
              Struttura Cartelle ZIP
            </h3>
            <p className="text-sm text-muted-foreground">
              Configura l'organizzazione delle cartelle nel file ZIP generato
            </p>
          </div>

          <div className="flex gap-2">
            <Button
              onClick={handleReset}
              variant="outline"
              size="sm"
              disabled={!hasChanges}
            >
              <RotateCcw className="mr-2 h-4 w-4" />
              Ripristina
            </Button>
            <Button
              onClick={handleSave}
              size="sm"
              disabled={!hasChanges}
              className="bg-gradient-to-r from-primary to-accent"
            >
              <Save className="mr-2 h-4 w-4" />
              Salva
            </Button>
          </div>
        </div>
      </Card>

      {/* Folders List */}
      <Card className="p-6">
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <h4 className="font-semibold">Cartelle</h4>
            <Button onClick={addFolder} variant="outline" size="sm">
              <Plus className="mr-2 h-4 w-4" />
              Aggiungi Cartella
            </Button>
          </div>

          <div className="space-y-2">
            {settings.folders
              .sort((a, b) => a.order - b.order)
              .map((folder, index) => (
                <Card
                  key={folder.id}
                  className={`p-4 border-l-4 ${folder.enabled
                    ? 'border-l-primary bg-card'
                    : 'border-l-muted bg-muted/20'
                    }`}
                >
                  <div className="flex items-center gap-4">
                    {/* Drag Handle */}
                    <div className="flex flex-col gap-1">
                      <Button
                        onClick={() => moveFolderUp(folder.id)}
                        disabled={index === 0}
                        variant="ghost"
                        size="sm"
                        className="h-6 w-6 p-0"
                      >
                        ▲
                      </Button>
                      <Button
                        onClick={() => moveFolderDown(folder.id)}
                        disabled={index === settings.folders.length - 1}
                        variant="ghost"
                        size="sm"
                        className="h-6 w-6 p-0"
                      >
                        ▼
                      </Button>
                    </div>

                    {/* Icon */}
                    <span className="text-2xl">{folder.icon}</span>

                    {/* Folder Name Input */}
                    <Input
                      value={folder.name}
                      onChange={(e) =>
                        updateFolderName(folder.id, e.target.value)
                      }
                      className="flex-1 max-w-xs"
                      disabled={!folder.enabled}
                    />

                    {/* File Types Badge */}
                    <div className="flex-1">
                      <span className="text-xs text-muted-foreground">
                        {folder.fileTypes.length > 0
                          ? folder.fileTypes.join(', ')
                          : 'Nessun tipo file'}
                      </span>
                    </div>

                    {/* Enabled Toggle */}
                    <div className="flex items-center gap-2">
                      <Label
                        htmlFor={`folder-${folder.id}`}
                        className="text-sm cursor-pointer"
                      >
                        Attiva
                      </Label>
                      <Switch
                        id={`folder-${folder.id}`}
                        checked={folder.enabled}
                        onCheckedChange={() => toggleFolder(folder.id)}
                      />
                    </div>

                    {/* Delete Button */}
                    <Button
                      onClick={() => removeFolder(folder.id)}
                      variant="ghost"
                      size="sm"
                      className="text-destructive hover:bg-destructive/10"
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>

                  {/* Template Assignment Section */}
                  {folder.enabled && (
                    <div className="mt-4 pt-4 border-t">
                      <Label className="text-xs font-semibold text-muted-foreground mb-2 block">
                        TEMPLATE ASSEGNATI
                      </Label>
                      <ScrollArea className="h-32 w-full rounded-md border p-2">
                        <div className="space-y-2">
                          {availableTemplates.map((template) => (
                            <div key={template.id} className="flex items-center space-x-2">
                              <Checkbox
                                id={`${folder.id}-${template.id}`}
                                checked={(folder.assignedTemplates || []).includes(template.id)}
                                onCheckedChange={() => toggleTemplateAssignment(folder.id, template.id)}
                              />
                              <label
                                htmlFor={`${folder.id}-${template.id}`}
                                className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70 cursor-pointer"
                              >
                                {template.name}
                                <span className="text-xs text-muted-foreground ml-1">
                                  ({template.type})
                                </span>
                              </label>
                            </div>
                          ))}
                        </div>
                      </ScrollArea>
                    </div>
                  )}
                </Card>
              ))}
          </div>
        </div>
      </Card>

      {/* General Options */}
      <Card className="p-6">
        <div className="space-y-4">
          <h4 className="font-semibold">Opzioni Generali</h4>

          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="timestamp" className="font-medium">
                  Includi Timestamp
                </Label>
                <p className="text-xs text-muted-foreground">
                  Aggiunge data e ora al nome del file ZIP
                </p>
              </div>
              <Switch
                id="timestamp"
                checked={settings.includeTimestamp}
                onCheckedChange={(checked) =>
                  setSettings((prev) => ({
                    ...prev,
                    includeTimestamp: checked,
                  }))
                }
              />
            </div>

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="course-id" className="font-medium">
                  Includi ID Corso nei Nomi File
                </Label>
                <p className="text-xs text-muted-foreground">
                  Aggiunge l'ID del corso a ogni nome file
                </p>
              </div>
              <Switch
                id="course-id"
                checked={settings.includeCourseIdInFilenames}
                onCheckedChange={(checked) =>
                  setSettings((prev) => ({
                    ...prev,
                    includeCourseIdInFilenames: checked,
                  }))
                }
              />
            </div>

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="readme" className="font-medium">
                  Genera README
                </Label>
                <p className="text-xs text-muted-foreground">
                  Crea un file README.txt con informazioni sul pacchetto
                </p>
              </div>
              <Switch
                id="readme"
                checked={settings.generateReadme}
                onCheckedChange={(checked) =>
                  setSettings((prev) => ({
                    ...prev,
                    generateReadme: checked,
                  }))
                }
              />
            </div>

            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="metadata" className="font-medium">
                  Genera Metadata JSON
                </Label>
                <p className="text-xs text-muted-foreground">
                  Crea un file metadata.json con i dati del corso
                </p>
              </div>
              <Switch
                id="metadata"
                checked={settings.generateMetadata}
                onCheckedChange={(checked) =>
                  setSettings((prev) => ({
                    ...prev,
                    generateMetadata: checked,
                  }))
                }
              />
            </div>
          </div>
        </div>
      </Card>

      {/* Changes Warning */}
      {hasChanges && (
        <Card className="p-4 bg-amber-50 dark:bg-amber-950 border-amber-200 dark:border-amber-800">
          <div className="flex items-center gap-2 text-amber-900 dark:text-amber-100">
            <span className="text-lg">⚠️</span>
            <p className="text-sm font-medium">
              Hai modifiche non salvate. Clicca "Salva" per applicare le modifiche.
            </p>
          </div>
        </Card>
      )}
    </div>
  );
};

import { loadFolderStructureSettings } from '@/utils/settingsUtils';

export default FolderStructureSettings;

/**
 * Predefined Data Settings Component
 *
 * Purpose: Manage predefined data for common fields that cannot be auto-extracted
 * Provides dropdown options for: locations, entities, responsables, supervisors, trainers, platforms
 */

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
    Database,
    Plus,
    Trash2,
    Save,
    MapPin,
    Building2,
    UserCheck,
    Users,
    GraduationCap,
    Video,
    Edit2,
    Check,
    X,
    Download,
    Upload,
    BookOpen,
} from 'lucide-react';
import { toast } from 'sonner';
import { Badge } from '@/components/ui/badge';
import {
    Accordion,
    AccordionContent,
    AccordionItem,
    AccordionTrigger,
} from '@/components/ui/accordion';
import { Switch } from '@/components/ui/switch';
import {
    loadPredefinedData,
    savePredefinedData,
    generatePredefinedDataId,
    validateCodiceFiscale,
    validateDateFormat,
    exportPredefinedData,
    importPredefinedData,
} from '@/utils/predefinedDataUtils';
import type {
    PredefinedDataSettings,
    PredefinedLocation,
    PredefinedEntity,
    PredefinedResponsabile,
    PredefinedSupervisor,
    PredefinedTrainer,
    PredefinedPlatform,
    PredefinedArgumentList,
} from '@/types/userSettings';

// ============================================================================
// COMPONENT
// ============================================================================

const PredefinedDataSettings = () => {
    const [data, setData] = useState<PredefinedDataSettings>(loadPredefinedData());
    const [editingId, setEditingId] = useState<string | null>(null);

    // Argument Lists State
    const [newArgListName, setNewArgListName] = useState('');
    const [newArgListContent, setNewArgListContent] = useState(''); // Newline separated

    // ========================================================================
    // SAVE HANDLER
    // ========================================================================

    const handleSave = () => {
        try {
            savePredefinedData(data);
            toast.success('Dati predefiniti salvati!');
        } catch (error) {
            toast.error('Errore durante il salvataggio');
        }
    };

    const handleExport = () => {
        try {
            exportPredefinedData();
            toast.success('Dati esportati con successo!');
        } catch (error) {
            toast.error('Errore durante l\'esportazione');
        }
    };

    const handleImport = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;

        try {
            const importedData = await importPredefinedData(file);
            setData(importedData);
            toast.success('Dati importati con successo!');
        } catch (error: any) {
            console.error('Import error:', error);
            toast.error(`Errore durante l'importazione: ${error.message || 'File non valido'}`);
        }

        // Reset input to allow re-importing the same file
        event.target.value = '';
    };

    // ========================================================================
    // LOCATIONS
    // ========================================================================

    const [newLocation, setNewLocation] = useState<Partial<PredefinedLocation>>({});

    const handleAddLocation = () => {
        if (!newLocation.name || !newLocation.address) {
            toast.error('Nome e indirizzo sono obbligatori');
            return;
        }

        const location: PredefinedLocation = {
            id: generatePredefinedDataId('location'),
            name: newLocation.name,
            address: newLocation.address,
            enabled: true,
        };

        setData((prev) => ({
            ...prev,
            locations: [...prev.locations, location],
        }));

        setNewLocation({});
        toast.success('Sede aggiunta!');
    };

    const handleRemoveLocation = (id: string) => {
        setData((prev) => ({
            ...prev,
            locations: prev.locations.filter((l) => l.id !== id),
        }));
        toast.success('Sede rimossa');
    };

    const handleToggleLocation = (id: string) => {
        setData((prev) => ({
            ...prev,
            locations: prev.locations.map((l) =>
                l.id === id ? { ...l, enabled: !l.enabled } : l
            ),
        }));
    };

    // ========================================================================
    // ENTITIES
    // ========================================================================

    const [newEntity, setNewEntity] = useState<Partial<PredefinedEntity>>({});

    const handleAddEntity = () => {
        if (!newEntity.name || !newEntity.address) {
            toast.error('Nome e indirizzo sono obbligatori');
            return;
        }

        const entity: PredefinedEntity = {
            id: generatePredefinedDataId('entity'),
            name: newEntity.name,
            address: newEntity.address,
            enabled: true,
        };

        setData((prev) => ({
            ...prev,
            entities: [...prev.entities, entity],
        }));

        setNewEntity({});
        toast.success('Ente aggiunto!');
    };

    const handleRemoveEntity = (id: string) => {
        setData((prev) => ({
            ...prev,
            entities: prev.entities.filter((e) => e.id !== id),
        }));
        toast.success('Ente rimosso');
    };

    const handleToggleEntity = (id: string) => {
        setData((prev) => ({
            ...prev,
            entities: prev.entities.map((e) =>
                e.id === id ? { ...e, enabled: !e.enabled } : e
            ),
        }));
    };

    // ========================================================================
    // TRAINERS
    // ========================================================================

    const [newTrainer, setNewTrainer] = useState<Partial<PredefinedTrainer>>({});

    const handleAddTrainer = () => {
        if (!newTrainer.nome || !newTrainer.cognome || !newTrainer.codiceFiscale) {
            toast.error('Nome, cognome e codice fiscale sono obbligatori');
            return;
        }

        if (!validateCodiceFiscale(newTrainer.codiceFiscale)) {
            toast.error('Codice fiscale non valido');
            return;
        }

        const trainer: PredefinedTrainer = {
            id: generatePredefinedDataId('trainer'),
            nome: newTrainer.nome,
            cognome: newTrainer.cognome,
            codiceFiscale: newTrainer.codiceFiscale.toUpperCase(),
            email: newTrainer.email || `${(newTrainer.nome || '').toLowerCase()}.${(newTrainer.cognome || '').toLowerCase()}@akgitalia.it`,
            telefono: newTrainer.telefono || '',
            enabled: true,
        };

        setData((prev) => ({
            ...prev,
            trainers: [...prev.trainers, trainer],
        }));

        setNewTrainer({});
        toast.success('Trainer aggiunto!');
    };

    const handleRemoveTrainer = (id: string) => {
        setData((prev) => ({
            ...prev,
            trainers: prev.trainers.filter((t) => t.id !== id),
        }));
        toast.success('Trainer rimosso');
    };

    const handleToggleTrainer = (id: string) => {
        setData((prev) => ({
            ...prev,
            trainers: prev.trainers.map((t) =>
                t.id === id ? { ...t, enabled: !t.enabled } : t
            ),
        }));
    };

    // ========================================================================
    // PLATFORMS
    // ========================================================================

    const [newPlatform, setNewPlatform] = useState<Partial<PredefinedPlatform>>({});

    const handleAddPlatform = () => {
        if (!newPlatform.name) {
            toast.error('Nome piattaforma obbligatorio');
            return;
        }

        const platform: PredefinedPlatform = {
            id: generatePredefinedDataId('platform'),
            name: newPlatform.name,
            link: newPlatform.link || undefined,
            meetingId: newPlatform.meetingId || undefined,
            accessCode: newPlatform.accessCode || undefined,
            enabled: true,
        };

        setData((prev) => ({
            ...prev,
            platforms: [...prev.platforms, platform],
        }));

        setNewPlatform({});
        toast.success('Piattaforma aggiunta!');
    };

    const handleRemovePlatform = (id: string) => {
        setData((prev) => ({
            ...prev,
            platforms: prev.platforms.filter((p) => p.id !== id),
        }));
        toast.success('Piattaforma rimossa');
    };

    const handleTogglePlatform = (id: string) => {
        setData((prev) => ({
            ...prev,
            platforms: prev.platforms.map((p) =>
                p.id === id ? { ...p, enabled: !p.enabled } : p
            ),
        }));
    };

    // ========================================================================
    // ARGUMENT LISTS
    // ========================================================================

    const handleAddArgList = () => {
        if (!newArgListName.trim()) {
            toast.error('Nome della lista obbligatorio');
            return;
        }

        const argumentsArray = newArgListContent
            .split('\n')
            .map((arg) => arg.trim())
            .filter((arg) => arg.length > 0);

        if (argumentsArray.length === 0) {
            toast.error('Inserisci almeno un argomento');
            return;
        }

        const argList: PredefinedArgumentList = {
            id: generatePredefinedDataId('arglist'),
            name: newArgListName.trim(),
            arguments: argumentsArray,
            enabled: true,
        };

        setData((prev) => ({
            ...prev,
            argumentLists: [...(prev.argumentLists || []), argList],
        }));

        setNewArgListName('');
        setNewArgListContent('');
        toast.success('Lista argomenti aggiunta!');
    };

    const handleRemoveArgList = (id: string) => {
        setData((prev) => ({
            ...prev,
            argumentLists: (prev.argumentLists || []).filter((a) => a.id !== id),
        }));
        toast.success('Lista argomenti rimossa');
    };

    const handleToggleArgList = (id: string) => {
        setData((prev) => ({
            ...prev,
            argumentLists: (prev.argumentLists || []).map((a) =>
                a.id === id ? { ...a, enabled: !a.enabled } : a
            ),
        }));
    };

    // ========================================================================
    // RESPONSABILI
    // ========================================================================

    const [newResponsabile, setNewResponsabile] = useState<Partial<PredefinedResponsabile>>({});

    const handleAddResponsabile = () => {
        if (!newResponsabile.nome || !newResponsabile.cognome || !newResponsabile.documento) {
            toast.error('Nome, cognome e documento sono obbligatori');
            return;
        }

        const responsabile: PredefinedResponsabile = {
            id: generatePredefinedDataId('responsabile'),
            nome: newResponsabile.nome,
            cognome: newResponsabile.cognome,
            dataNascita: newResponsabile.dataNascita || '',
            cittaNascita: newResponsabile.cittaNascita || '',
            provinciaNascita: newResponsabile.provinciaNascita || '',
            cittaResidenza: newResponsabile.cittaResidenza || '',
            viaResidenza: newResponsabile.viaResidenza || '',
            numeroCivico: newResponsabile.numeroCivico || '',
            documento: newResponsabile.documento,
            enabled: true,
        };

        setData((prev) => ({
            ...prev,
            responsabili: [...prev.responsabili, responsabile],
        }));

        setNewResponsabile({});
        toast.success('Responsabile aggiunto!');
    };

    const handleRemoveResponsabile = (id: string) => {
        setData((prev) => ({
            ...prev,
            responsabili: prev.responsabili.filter((r) => r.id !== id),
        }));
        toast.success('Responsabile rimosso');
    };

    const handleToggleResponsabile = (id: string) => {
        setData((prev) => ({
            ...prev,
            responsabili: prev.responsabili.map((r) =>
                r.id === id ? { ...r, enabled: !r.enabled } : r
            ),
        }));
    };

    // ========================================================================
    // SUPERVISORI
    // ========================================================================

    const [newSupervisor, setNewSupervisor] = useState<Partial<PredefinedSupervisor>>({});

    const handleAddSupervisor = () => {
        if (!newSupervisor.nome || !newSupervisor.cognome) {
            toast.error('Nome e cognome sono obbligatori');
            return;
        }

        const supervisor: PredefinedSupervisor = {
            id: generatePredefinedDataId('supervisor'),
            nome: newSupervisor.nome,
            cognome: newSupervisor.cognome,
            qualifica: newSupervisor.qualifica || 'Supervisore',
            enabled: true,
        };

        setData((prev) => ({
            ...prev,
            supervisors: [...prev.supervisors, supervisor],
        }));

        setNewSupervisor({});
        toast.success('Supervisore aggiunto!');
    };

    const handleRemoveSupervisor = (id: string) => {
        setData((prev) => ({
            ...prev,
            supervisors: prev.supervisors.filter((s) => s.id !== id),
        }));
        toast.success('Supervisore rimosso');
    };

    const handleToggleSupervisor = (id: string) => {
        setData((prev) => ({
            ...prev,
            supervisors: prev.supervisors.map((s) =>
                s.id === id ? { ...s, enabled: !s.enabled } : s
            ),
        }));
    };

    // ========================================================================
    // RENDER
    // ========================================================================

    return (
        <div className="space-y-6">
            {/* Header */}
            <Card>
                <CardHeader>
                    <div className="flex items-center justify-between">
                        <div className="space-y-1">
                            <CardTitle className="flex items-center gap-2">
                                <Database className="h-5 w-5 text-primary" />
                                Dati Predefiniti
                            </CardTitle>
                            <CardDescription>
                                Configura dati riutilizzabili che appariranno come opzioni nei menu a tendina del wizard
                            </CardDescription>
                        </div>
                        <div className="flex gap-2">
                            <div className="relative">
                                <input
                                    type="file"
                                    accept=".json"
                                    onChange={handleImport}
                                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                                />
                                <Button variant="outline" size="sm" className="gap-2">
                                    <Upload className="h-4 w-4" />
                                    Importa
                                </Button>
                            </div>
                            <Button variant="outline" size="sm" onClick={handleExport} className="gap-2">
                                <Download className="h-4 w-4" />
                                Esporta
                            </Button>
                            <Button onClick={handleSave} size="sm" className="gap-2">
                                <Save className="h-4 w-4" />
                                Salva
                            </Button>
                        </div>
                    </div>
                </CardHeader>
            </Card>

            {/* Accordion for Categories */}
            <Accordion type="multiple" className="space-y-4">
                {/* LOCATIONS */}
                <AccordionItem value="locations">
                    <Card>
                        <AccordionTrigger className="px-6 hover:no-underline">
                            <div className="flex items-center gap-3">
                                <MapPin className="h-5 w-5 text-primary" />
                                <div className="text-left">
                                    <h3 className="font-semibold">Sedi Accreditate</h3>
                                    <p className="text-sm text-muted-foreground">
                                        {data.locations.length} sedi configurate
                                    </p>
                                </div>
                            </div>
                        </AccordionTrigger>
                        <AccordionContent>
                            <CardContent className="space-y-4">
                                {/* Add New Form */}
                                <div className="grid grid-cols-2 gap-3 p-4 bg-accent/5 rounded-lg">
                                    <Input
                                        placeholder="Nome sede"
                                        value={newLocation.name || ''}
                                        onChange={(e) => setNewLocation({ ...newLocation, name: e.target.value })}
                                    />
                                    <Input
                                        placeholder="Indirizzo completo"
                                        value={newLocation.address || ''}
                                        onChange={(e) => setNewLocation({ ...newLocation, address: e.target.value })}
                                    />
                                    <Button onClick={handleAddLocation} size="sm" className="col-span-2">
                                        <Plus className="mr-2 h-4 w-4" />
                                        Aggiungi Sede
                                    </Button>
                                </div>

                                {/* List */}
                                {data.locations.length > 0 ? (
                                    <div className="space-y-2">
                                        {data.locations.map((location) => (
                                            <div
                                                key={location.id}
                                                className="flex items-center justify-between p-3 border rounded-lg"
                                            >
                                                <div className="flex-1">
                                                    <p className="font-medium">{location.name}</p>
                                                    <p className="text-sm text-muted-foreground">{location.address}</p>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <Switch
                                                        checked={location.enabled}
                                                        onCheckedChange={() => handleToggleLocation(location.id)}
                                                    />
                                                    <Button
                                                        onClick={() => handleRemoveLocation(location.id)}
                                                        variant="ghost"
                                                        size="sm"
                                                        className="text-destructive"
                                                    >
                                                        <Trash2 className="h-4 w-4" />
                                                    </Button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <p className="text-center text-sm text-muted-foreground py-4">
                                        Nessuna sede configurata
                                    </p>
                                )}
                            </CardContent>
                        </AccordionContent>
                    </Card>
                </AccordionItem>

                {/* ENTITIES */}
                <AccordionItem value="entities">
                    <Card>
                        <AccordionTrigger className="px-6 hover:no-underline">
                            <div className="flex items-center gap-3">
                                <Building2 className="h-5 w-5 text-primary" />
                                <div className="text-left">
                                    <h3 className="font-semibold">Enti</h3>
                                    <p className="text-sm text-muted-foreground">
                                        {data.entities.length} enti configurati
                                    </p>
                                </div>
                            </div>
                        </AccordionTrigger>
                        <AccordionContent>
                            <CardContent className="space-y-4">
                                {/* Add New Form */}
                                <div className="grid grid-cols-2 gap-3 p-4 bg-accent/5 rounded-lg">
                                    <Input
                                        placeholder="Nome ente"
                                        value={newEntity.name || ''}
                                        onChange={(e) => setNewEntity({ ...newEntity, name: e.target.value })}
                                    />
                                    <Input
                                        placeholder="Indirizzo completo"
                                        value={newEntity.address || ''}
                                        onChange={(e) => setNewEntity({ ...newEntity, address: e.target.value })}
                                    />
                                    <Button onClick={handleAddEntity} size="sm" className="col-span-2">
                                        <Plus className="mr-2 h-4 w-4" />
                                        Aggiungi Ente
                                    </Button>
                                </div>

                                {/* List */}
                                {data.entities.length > 0 ? (
                                    <div className="space-y-2">
                                        {data.entities.map((entity) => (
                                            <div
                                                key={entity.id}
                                                className="flex items-center justify-between p-3 border rounded-lg"
                                            >
                                                <div className="flex-1">
                                                    <p className="font-medium">{entity.name}</p>
                                                    <p className="text-sm text-muted-foreground">{entity.address}</p>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <Switch
                                                        checked={entity.enabled}
                                                        onCheckedChange={() => handleToggleEntity(entity.id)}
                                                    />
                                                    <Button
                                                        onClick={() => handleRemoveEntity(entity.id)}
                                                        variant="ghost"
                                                        size="sm"
                                                        className="text-destructive"
                                                    >
                                                        <Trash2 className="h-4 w-4" />
                                                    </Button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <p className="text-center text-sm text-muted-foreground py-4">
                                        Nessun ente configurato
                                    </p>
                                )}
                            </CardContent>
                        </AccordionContent>
                    </Card>
                </AccordionItem>

                {/* RESPONSABILI */}
                <AccordionItem value="responsabili">
                    <Card>
                        <AccordionTrigger className="px-6 hover:no-underline">
                            <div className="flex items-center gap-3">
                                <UserCheck className="h-5 w-5 text-primary" />
                                <div className="text-left">
                                    <h3 className="font-semibold">Responsabili Certificazione</h3>
                                    <p className="text-sm text-muted-foreground">
                                        {data.responsabili.length} responsabili configurati
                                    </p>
                                </div>
                            </div>
                        </AccordionTrigger>
                        <AccordionContent>
                            <CardContent className="space-y-4">
                                {/* Add New Form */}
                                <div className="grid grid-cols-2 gap-3 p-4 bg-accent/5 rounded-lg">
                                    <Input
                                        placeholder="Nome"
                                        value={newResponsabile.nome || ''}
                                        onChange={(e) => setNewResponsabile({ ...newResponsabile, nome: e.target.value })}
                                    />
                                    <Input
                                        placeholder="Cognome"
                                        value={newResponsabile.cognome || ''}
                                        onChange={(e) => setNewResponsabile({ ...newResponsabile, cognome: e.target.value })}
                                    />
                                    <Input
                                        placeholder="Data di Nascita (GG/MM/AAAA)"
                                        value={newResponsabile.dataNascita || ''}
                                        onChange={(e) => setNewResponsabile({ ...newResponsabile, dataNascita: e.target.value })}
                                    />
                                    <Input
                                        placeholder="Città di Nascita"
                                        value={newResponsabile.cittaNascita || ''}
                                        onChange={(e) => setNewResponsabile({ ...newResponsabile, cittaNascita: e.target.value })}
                                    />
                                    <Input
                                        placeholder="Provincia Nascita"
                                        value={newResponsabile.provinciaNascita || ''}
                                        onChange={(e) => setNewResponsabile({ ...newResponsabile, provinciaNascita: e.target.value })}
                                    />
                                    <Input
                                        placeholder="Città Residenza"
                                        value={newResponsabile.cittaResidenza || ''}
                                        onChange={(e) => setNewResponsabile({ ...newResponsabile, cittaResidenza: e.target.value })}
                                    />
                                    <Input
                                        placeholder="Via Residenza"
                                        value={newResponsabile.viaResidenza || ''}
                                        onChange={(e) => setNewResponsabile({ ...newResponsabile, viaResidenza: e.target.value })}
                                    />
                                    <Input
                                        placeholder="N. Civico"
                                        value={newResponsabile.numeroCivico || ''}
                                        onChange={(e) => setNewResponsabile({ ...newResponsabile, numeroCivico: e.target.value })}
                                    />
                                    <Input
                                        placeholder="Documento Identità"
                                        className="col-span-2"
                                        value={newResponsabile.documento || ''}
                                        onChange={(e) => setNewResponsabile({ ...newResponsabile, documento: e.target.value })}
                                    />
                                    <Button onClick={handleAddResponsabile} size="sm" className="col-span-2">
                                        <Plus className="mr-2 h-4 w-4" />
                                        Aggiungi Responsabile
                                    </Button>
                                </div>

                                {/* List */}
                                {data.responsabili.length > 0 ? (
                                    <div className="space-y-2">
                                        {data.responsabili.map((resp) => (
                                            <div
                                                key={resp.id}
                                                className="flex items-center justify-between p-3 border rounded-lg"
                                            >
                                                <div className="flex-1">
                                                    <p className="font-medium">
                                                        {resp.nome} {resp.cognome}
                                                    </p>
                                                    <p className="text-sm text-muted-foreground">
                                                        {resp.documento}
                                                    </p>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <Switch
                                                        checked={resp.enabled}
                                                        onCheckedChange={() => handleToggleResponsabile(resp.id)}
                                                    />
                                                    <Button
                                                        onClick={() => handleRemoveResponsabile(resp.id)}
                                                        variant="ghost"
                                                        size="sm"
                                                        className="text-destructive"
                                                    >
                                                        <Trash2 className="h-4 w-4" />
                                                    </Button>
                                                </div>
                                            </div>
                                        ))}
