      setNomeDocente('');
      setCognomeDocente('');
      setEmailDocente('');
      setTelefonoDocente('');
    }
  };

  /**
   * Handles supervisor selection from dropdown
   */
  const handleSupervisorSelect = (value: string) => {
    setSelectedSupervisorId(value);

    if (value !== CUSTOM_OPTION_VALUE) {
      const supervisor = findSupervisorById(value);
      if (supervisor) {
        setNomeSupervisore(supervisor.nome);
        setCognomeSupervisore(supervisor.cognome);
      }
    } else {
      // Clear fields when "Custom" is selected
      setNomeSupervisore('');
      setCognomeSupervisore('');
    }
  };

  /**
   * Handles location selection from dropdown
   */
  const handleLocationSelect = (value: string) => {
    setSelectedLocationId(value);

    if (value !== CUSTOM_OPTION_VALUE) {
      const location = findLocationById(value);
      if (location) {
        setSedeAccreditata(location.name);
        setIndirizzoSede(location.address);
        setCittaSede(location.city || '');
        setCapSede(location.cap || '');
        setProvinciaSede(location.province || '');

        // Auto-select Ente if linked
        if (location.enteId) {
          // Logic to select Ente would go here if Ente selection was in this component
          // Currently Ente selection is in CompletionStep, but we pass the ID
        }
      }
    } else {
      setSedeAccreditata('');
      setIndirizzoSede('');
      setCittaSede('');
      setCapSede('');
      setProvinciaSede('');
    }
  };

  /**
   * Validates Codice Fiscale format
   */
  const validateCodiceFiscale = (cf: string): boolean => {
    const cfUpper = cf.toUpperCase().trim();
    if (!VALIDATION_PATTERNS.CODICE_FISCALE.test(cfUpper)) {
      toast.error(ERROR_MESSAGES.INVALID_CF);
      return false;
    }
    return true;
  };

  /**
   * Validates Zoom link format (optional field)
   */
  const validateZoomLink = (link: string): boolean => {
    if (!link.trim()) return true; // Optional field

    if (!VALIDATION_PATTERNS.ZOOM_LINK.test(link.trim())) {
      toast.error(ERROR_MESSAGES.INVALID_ZOOM);
      return false;
    }
    return true;
  };

  /**
   * Handles form submission
   */
  const handleSubmit = () => {
    // Validate required fields
    if (!codiceFiscaleDocente.trim()) {
      toast.error(ERROR_MESSAGES.EMPTY_CF);
      return;
    }

    if (!validateCodiceFiscale(codiceFiscaleDocente)) {
      return;
    }

    if (!validateZoomLink(linkZoom)) {
      return;
    }

    // All validations passed
    const data: AdditionalData = {
      codiceFiscaleDocente: codiceFiscaleDocente.toUpperCase().trim(),
      nomeDocente: nomeDocente.trim() || undefined,
      cognomeDocente: cognomeDocente.trim() || undefined,
      emailDocente: emailDocente.trim() || undefined,
      telefonoDocente: telefonoDocente.trim() || undefined,
      nomeSupervisore: nomeSupervisore.trim() || undefined,
      cognomeSupervisore: cognomeSupervisore.trim() || undefined,
      linkZoom: linkZoom.trim() || undefined,
      idRiunione: idRiunione.trim() || undefined,
      passcode: passcode.trim() || undefined,
      piattaforma: (selectedPlatform && selectedPlatform !== 'NONE') ? selectedPlatform : undefined,
      sedeAccreditata: sedeAccreditata.trim() || undefined,
      indirizzoSede: indirizzoSede.trim() || undefined,
      cittaSede: cittaSede.trim() || undefined,
      capSede: capSede.trim() || undefined,
      provinciaSede: provinciaSede.trim() || undefined,
      nomeEnte: nomeEnte.trim() || undefined,
      indirizzoEnte: indirizzoEnte.trim() || undefined,
      note: note.trim() || undefined,
      enteAccreditatoId: selectedLocationId !== CUSTOM_OPTION_VALUE ? selectedLocationId : undefined,
      idOffertaFormativa: idOffertaFormativa === 'CUSTOM' ? customIdOfferta : idOffertaFormativa,
    };

    onComplete(data);
  };

  /**
   * Auto-formats Codice Fiscale to uppercase
   */
  const handleCFChange = (value: string) => {
    setCodiceFiscaleDocente(value.toUpperCase());
    // Reset trainer selection if manually editing
    if (selectedTrainerId !== CUSTOM_OPTION_VALUE) {
      setSelectedTrainerId(CUSTOM_OPTION_VALUE);
    }
  };

  // Auto-select predefined options using the closest match from extracted data
  useEffect(() => {
    if (autoMatchApplied || !initialData) return;

    const trainerMatch =
      availableTrainers.find(
        (trainer) => normalizeCodiceFiscale(trainer.codiceFiscale) === normalizeCodiceFiscale(initialData.codiceFiscaleDocente)
      ) ||
      findBestMatch(
        availableTrainers,
        [
          `${initialData.nomeDocente || ''} ${initialData.cognomeDocente || ''}`,
          initialData.codiceFiscaleDocente
        ],
        (trainer) => [
          `${trainer.nome || ''} ${trainer.cognome || ''}`,
          trainer.nomeCompleto || '',
          trainer.codiceFiscale || ''
        ],
        TRAINER_NAME_THRESHOLD
      )?.item;

    if (trainerMatch) {
      handleTrainerSelect(trainerMatch.id);
    }

    const supervisorMatch = findBestMatch(
      availableSupervisors,
      [
        `${initialData.nomeSupervisore || ''} ${initialData.cognomeSupervisore || ''}`
      ],
      (supervisor) => [
        `${supervisor.nome || ''} ${supervisor.cognome || ''}`
      ],
      TRAINER_NAME_THRESHOLD
    )?.item;

    if (supervisorMatch) {
      handleSupervisorSelect(supervisorMatch.id);
    }

    const locationMatch = findBestMatch(
      availableLocations,
      [initialData.sedeAccreditata, initialData.indirizzoSede],
      (location) => [location.name, location.address]
    );

    if (locationMatch) {
      handleLocationSelect(locationMatch.item.id);
    }

    const platformMatch = findBestMatch(
      availablePlatforms,
      [initialData.piattaforma],
      (platform) => [platform.name],
      0.5
    );

    if (platformMatch) {
      setSelectedPlatform(platformMatch.item.name);
    } else if (initialData.piattaforma && !selectedPlatform) {
      setSelectedPlatform(initialData.piattaforma);
    }

    setAutoMatchApplied(true);
  }, [
    availableLocations,
    availablePlatforms,
    availableTrainers,
    autoMatchApplied,
    handleLocationSelect,
    handleTrainerSelect,
    initialData,
    selectedPlatform
  ]);

  const hasTrainers = availableTrainers.length > 0;
  const hasSupervisors = availableSupervisors.length > 0;
  const hasLocations = availableLocations.length > 0;
  const hasPlatforms = availablePlatforms.length > 0;

  return (
    <Card className="p-8 shadow-xl">
      <div className="space-y-6">
        {/* Header */}
        <div className="text-center space-y-2">
          <div className="inline-flex h-16 w-16 items-center justify-center rounded-full bg-gradient-to-br from-primary/10 to-accent/10 mb-4">
            <UserCheck className="h-8 w-8 text-primary" />
          </div>
          <h3 className="text-xl font-bold text-foreground">
            Dati Aggiuntivi
          </h3>
          <p className="text-muted-foreground max-w-lg mx-auto">
            Inserisci le informazioni che non possono essere estratte dal
            gestionale
          </p>
        </div>

        {/* Form Fields */}
        <div className="space-y-5">
          {/* ID OFFERTA FORMATIVA */}
          <div className="space-y-3 p-4 border rounded-lg bg-accent/5">
            <Label className="text-base font-semibold flex items-center gap-2">
              <FileText className="h-4 w-4 text-primary" />
              Dati Offerta Formativa
            </Label>

            <div className="space-y-2">
              <Label htmlFor="id-offerta" className="text-sm">ID Offerta Formativa</Label>
              <Select value={idOffertaFormativa} onValueChange={setIdOffertaFormativa}>
                <SelectTrigger id="id-offerta">
                  <SelectValue placeholder="Seleziona ID Offerta..." />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="1020">1020 - GOL (Inserimento lavorativo)</SelectItem>
                  <SelectItem value="1540">1540 - GOL FAD 100% (Inserimento lavorativo)</SelectItem>
                  <SelectItem value="CUSTOM">✏️ Altro (Inserisci manualmente)</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {idOffertaFormativa === 'CUSTOM' && (
              <div className="space-y-2 animate-in fade-in slide-in-from-top-2">
                <Label htmlFor="custom-id-offerta" className="text-sm">ID Personalizzato</Label>
                <Input
                  id="custom-id-offerta"
                  value={customIdOfferta}
                  onChange={(e) => setCustomIdOfferta(e.target.value)}
                  placeholder="Es. 2040"
                />
              </div>
            )}
          </div>

          {/* TRAINER/DOCENTE - with predefined dropdown */}
          <div className="space-y-3 p-4 border rounded-lg bg-accent/5">
            <div className="flex items-center justify-between">
              <Label className="text-base font-semibold flex items-center gap-2">
                <UserCheck className="h-4 w-4 text-primary" />
                Direttore del Corso / Docente *
              </Label>
              {hasTrainers && (
                <span className="text-xs text-muted-foreground">
                  {availableTrainers.length} predefiniti disponibili
                </span>
              )}
            </div>

            {hasTrainers && (
              <div className="space-y-2">
                <Label htmlFor="trainer-select" className="text-sm">Seleziona da predefiniti</Label>
                <Select value={selectedTrainerId} onValueChange={handleTrainerSelect}>
                  <SelectTrigger id="trainer-select">
                    <SelectValue placeholder="Scegli un trainer..." />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value={CUSTOM_OPTION_VALUE}>
                      ✏️ Inserimento manuale
                    </SelectItem>
                    {availableTrainers.map((trainer) => (
                      <SelectItem key={trainer.id} value={trainer.id}>
                        {trainer.nome} {trainer.cognome} - {trainer.codiceFiscale}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}
            <p className="text-xs text-muted-foreground">
              Il docente indicato verrà usato come riferimento per il direttore del corso.
            </p>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label htmlFor="nome-docente" className="text-sm">Nome</Label>
                <Input
                  id="nome-docente"
                  value={nomeDocente}
                  onChange={(e) => setNomeDocente(e.target.value)}
                  placeholder="Mario"
                  disabled={selectedTrainerId !== CUSTOM_OPTION_VALUE && hasTrainers}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="cognome-docente" className="text-sm">Cognome</Label>
                <Input
                  id="cognome-docente"
                  value={cognomeDocente}
                  onChange={(e) => setCognomeDocente(e.target.value)}
                  placeholder="Rossi"
                  disabled={selectedTrainerId !== CUSTOM_OPTION_VALUE && hasTrainers}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="codice-fiscale" className="text-sm font-semibold">
                Codice Fiscale *
              </Label>
              <Input
                id="codice-fiscale"
                value={codiceFiscaleDocente}
                onChange={(e) => handleCFChange(e.target.value)}
                placeholder="RSSMRA80A01H501Z"
                className="font-mono text-sm uppercase"
                maxLength={16}
                required
                disabled={selectedTrainerId !== CUSTOM_OPTION_VALUE && hasTrainers}
              />
              <p className="text-xs text-muted-foreground">
                Codice fiscale del docente/direttore (16 caratteri)
              </p>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label htmlFor="email-docente" className="text-sm">Email</Label>
                <Input
                  id="email-docente"
                  type="email"
                  value={emailDocente}
                  onChange={(e) => setEmailDocente(e.target.value)}
                  placeholder="nome.cognome@akgitalia.it"
                />
                <p className="text-xs text-muted-foreground">
                  Suggerita automaticamente da nome e cognome
                </p>
              </div>
              <div className="space-y-2">
                <Label htmlFor="tel-docente" className="text-sm">Telefono</Label>
                <Input
                  id="tel-docente"
                  value={telefonoDocente}
                  onChange={(e) => setTelefonoDocente(e.target.value)}
                  placeholder="+39 333 1234567"
                />
              </div>
            </div>
          </div>

          {/* SUPERVISORE - with predefined dropdown */}
          <div className="space-y-3 p-4 border rounded-lg bg-accent/5">
            <div className="flex items-center justify-between">
              <Label className="text-base font-semibold flex items-center gap-2">
                <UserCheck className="h-4 w-4 text-primary" />
                Supervisore (opzionale)
              </Label>
              {hasSupervisors && (
                <span className="text-xs text-muted-foreground">
                  {availableSupervisors.length} predefiniti disponibili
                </span>
              )}
            </div>

            {hasSupervisors && (
              <div className="space-y-2">
                <Label htmlFor="supervisor-select" className="text-sm">Seleziona da predefiniti</Label>
                <Select value={selectedSupervisorId} onValueChange={handleSupervisorSelect}>
                  <SelectTrigger id="supervisor-select">
                    <SelectValue placeholder="Scegli un supervisore..." />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value={CUSTOM_OPTION_VALUE}>
                      ✏️ Inserimento manuale
                    </SelectItem>
                    {availableSupervisors.map((supervisor) => (
                      <SelectItem key={supervisor.id} value={supervisor.id}>
                        {supervisor.nome} {supervisor.cognome}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label htmlFor="nome-supervisore" className="text-sm">Nome</Label>
                <Input
                  id="nome-supervisore"
                  value={nomeSupervisore}
                  onChange={(e) => setNomeSupervisore(e.target.value)}
                  placeholder="Nome"
                  disabled={selectedSupervisorId !== CUSTOM_OPTION_VALUE && hasSupervisors}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="cognome-supervisore" className="text-sm">Cognome</Label>
                <Input
                  id="cognome-supervisore"
                  value={cognomeSupervisore}
                  onChange={(e) => setCognomeSupervisore(e.target.value)}
                  placeholder="Cognome"
                  disabled={selectedSupervisorId !== CUSTOM_OPTION_VALUE && hasSupervisors}
                />
              </div>
            </div>
          </div>

          {/* SUPERVISORE - with predefined dropdown */}
          <div className="space-y-3 p-4 border rounded-lg bg-accent/5">
            <div className="flex items-center justify-between">
              <Label className="text-base font-semibold flex items-center gap-2">
                <UserCheck className="h-4 w-4 text-primary" />
                Supervisore (opzionale)
              </Label>
              {hasSupervisors && (
                <span className="text-xs text-muted-foreground">
                  {availableSupervisors.length} predefiniti disponibili
                </span>
              )}
            </div>

            {hasSupervisors && (
              <div className="space-y-2">
                <Label htmlFor="supervisor-select" className="text-sm">Seleziona da predefiniti</Label>
                <Select value={selectedSupervisorId} onValueChange={handleSupervisorSelect}>
                  <SelectTrigger id="supervisor-select">
                    <SelectValue placeholder="Scegli un supervisore..." />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value={CUSTOM_OPTION_VALUE}>
                      ✏️ Inserimento manuale
                    </SelectItem>
                    {availableSupervisors.map((supervisor) => (
                      <SelectItem key={supervisor.id} value={supervisor.id}>
                        {supervisor.nome} {supervisor.cognome}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label htmlFor="nome-supervisore" className="text-sm">Nome</Label>
                <Input
                  id="nome-supervisore"
                  value={nomeSupervisore}
                  onChange={(e) => setNomeSupervisore(e.target.value)}
                  placeholder="Nome"
                  disabled={selectedSupervisorId !== CUSTOM_OPTION_VALUE && hasSupervisors}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="cognome-supervisore" className="text-sm">Cognome</Label>
                <Input
                  id="cognome-supervisore"
                  value={cognomeSupervisore}
                  onChange={(e) => setCognomeSupervisore(e.target.value)}
                  placeholder="Cognome"
                  disabled={selectedSupervisorId !== CUSTOM_OPTION_VALUE && hasSupervisors}
                />
              </div>
            </div>
          </div>

          {/* SEDE ACCREDITATA - with predefined dropdown */}
          <div className="space-y-3 p-4 border rounded-lg bg-accent/5">
            <div className="flex items-center justify-between">
              <Label className="text-base font-semibold flex items-center gap-2">
                <MapPin className="h-4 w-4 text-primary" />
                Sede Accreditata (opzionale)
              </Label>
              {hasLocations && (
                <span className="text-xs text-muted-foreground">
                  {availableLocations.length} sedi disponibili
                </span>
              )}
            </div>

            {hasLocations && (
              <div className="space-y-2">
                <Label htmlFor="location-select" className="text-sm">Seleziona sede</Label>
                <Select value={selectedLocationId} onValueChange={handleLocationSelect}>
                  <SelectTrigger id="location-select">
                    <SelectValue placeholder="Scegli una sede..." />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value={CUSTOM_OPTION_VALUE}>
                      ✏️ Inserimento manuale
                    </SelectItem>
                    {availableLocations.map((location) => (
                      <SelectItem key={location.id} value={location.id}>
                        {location.name} - {location.address}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            <div className="space-y-2">
              <Label htmlFor="sede-nome" className="text-sm">Nome Sede</Label>
              <Input
                id="sede-nome"
                value={sedeAccreditata}
                onChange={(e) => setSedeAccreditata(e.target.value)}
                placeholder="Sede Milano"
                disabled={selectedLocationId !== CUSTOM_OPTION_VALUE && hasLocations}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="sede-indirizzo" className="text-sm">Indirizzo</Label>
              <Input
                id="sede-indirizzo"
                value={indirizzoSede}
                onChange={(e) => setIndirizzoSede(e.target.value)}
                placeholder="Via Roma 1, Milano"
                disabled={selectedLocationId !== CUSTOM_OPTION_VALUE && hasLocations}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="sede-citta" className="text-sm">Città</Label>
              <Input
                id="sede-citta"
                value={cittaSede}
                onChange={(e) => setCittaSede(e.target.value)}
                placeholder="Milano"
                disabled={selectedLocationId !== CUSTOM_OPTION_VALUE && hasLocations}
              />
            </div>
          </div>

          <p className="text-xs text-muted-foreground italic px-1">
            La scelta dell&apos;ente accreditato avverrà nel prossimo step di completamento dati.
          </p>

          {/* PIATTAFORMA FAD + LINK ZOOM */}
          <div className="space-y-3 p-4 border rounded-lg bg-accent/5">
            <Label className="text-base font-semibold flex items-center gap-2">
              <Video className="h-4 w-4 text-primary" />
              Piattaforma FAD (opzionale)
            </Label>

            {hasPlatforms && (
              <div className="space-y-2">
                <Label htmlFor="platform-select" className="text-sm">Piattaforma</Label>
                <Select value={selectedPlatform} onValueChange={setSelectedPlatform}>
                  <SelectTrigger id="platform-select">
                    <SelectValue placeholder="Seleziona piattaforma..." />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="NONE">Nessuna</SelectItem>
                    {availablePlatforms.map((platform) => (
                      <SelectItem key={platform.id} value={platform.name}>
                        {platform.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            )}

            <div className="space-y-2">
              <Label htmlFor="link-zoom" className="text-sm">Link Sessione Online</Label>
              <Input
                id="link-zoom"
                value={linkZoom}
                onChange={(e) => setLinkZoom(e.target.value)}
                placeholder="https://zoom.us/j/123456789"
                className="text-sm"
                type="url"
              />
              <p className="text-xs text-muted-foreground">
                Link della sessione (Zoom, Teams, Google Meet, ecc.)
              </p>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label htmlFor="id-riunione" className="text-sm">Codice Riunione</Label>
                <Input
                  id="id-riunione"
                  value={idRiunione}
                  onChange={(e) => setIdRiunione(e.target.value)}
                  placeholder="123 456 7890"
                  className="text-sm"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="passcode" className="text-sm">Codice Accesso</Label>
                <Input
                  id="passcode"
                  value={passcode}
                  onChange={(e) => setPasscode(e.target.value)}
                  placeholder="123456"
                  className="text-sm"
                />
              </div>
            </div>
          </div>

          {/* Note - OPTIONAL */}
          <div className="space-y-2">
            <Label htmlFor="note" className="text-base font-semibold">
              Note Aggiuntive (opzionale)
            </Label>
            <Textarea
              id="note"
              value={note}
              onChange={(e) => setNote(e.target.value)}
              placeholder="Eventuali note o informazioni aggiuntive..."
              className="text-sm min-h-[80px]"
              rows={3}
            />
          </div>
        </div>

        {/* Action Buttons */}
        <div className="flex gap-3 pt-4">
          {onBack && (
            <Button
              onClick={onBack}
              variant="outline"
              className="h-12"
            >
              Indietro
            </Button>
          )}
          <Button
            onClick={handleSubmit}
            className="flex-1 h-12 text-base font-semibold bg-gradient-to-r from-primary to-accent hover:opacity-90"
          >
            Continua
            <ChevronRight className="ml-2 h-5 w-5" />
          </Button>
        </div>

        {/* Info Box */}
        <Card className="p-4 bg-primary/5 border-primary/20">
          <div className="flex items-start gap-3">
            <div className="h-8 w-8 rounded-full bg-primary/10 flex items-center justify-center flex-shrink-0">
              <SettingsIcon className="h-4 w-4 text-primary" />
            </div>
            <div className="space-y-1">
              <h4 className="font-semibold text-sm text-foreground">
                💡 Suggerimento
              </h4>
              <p className="text-xs text-muted-foreground">
                Configura i dati predefiniti nelle <strong>Impostazioni</strong> per avere
                un accesso rapido a trainer, sedi ed enti ricorrenti. Questo velocizzerà
                il processo di compilazione!
              </p>
            </div>
          </div>
        </Card>
      </div>
    </Card>
  );
};

export default AdditionalDataStep;

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { CheckCircle, ChevronLeft, ArrowRight, User, Calendar, FileText } from "lucide-react";
import { toast } from "sonner";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";

interface ExtractedDataType {
  corso?: {
    id?: string;
    titolo?: string;
    data_inizio?: string;
    data_fine?: string;
  };
  partecipanti?: any[]; // Keep any for participants for now, can be refined later if needed
}

interface CompletionStepProps {
  extractedData: ExtractedDataType;
  onComplete: (data: ExtractedDataType & typeof formData) => void;
  onBack: () => void;
}

const CompletionStep = ({ extractedData, onComplete, onBack }: CompletionStepProps) => {
  const [formData, setFormData] = useState({
    direttore: "",
    supervisore: "",
    responsabile_nome: "",
    responsabile_cognome: "",
    responsabile_cf: "",
    ente_accreditato: "",
    sede_ente: "",
    argomenti_lezione_1: "",
    argomenti_lezione_2: "",
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    
    // Validate required fields
    if (!formData.direttore || !formData.responsabile_nome || !formData.responsabile_cognome) {
      toast.error("Compila tutti i campi obbligatori");
      return;
    }

    const completeData = {
      ...extractedData,
      ...formData,
    };

    toast.success("Dati completati con successo!");
    onComplete(completeData);
  };

  const updateField = (field: string, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  return (
    <Card className="p-8 shadow-xl">
      <div className="space-y-6">
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <h2 className="text-2xl font-bold text-foreground">Completa i Dati Mancanti</h2>
            <p className="text-muted-foreground">
              L'AI ha estratto la maggior parte delle informazioni. Completa i campi rimanenti.
            </p>
          </div>
          <Button variant="ghost" onClick={onBack}>
            <ChevronLeft className="mr-2 h-4 w-4" />
            Indietro
          </Button>
        </div>

        {/* Extracted Data Summary */}
        <Card className="p-4 bg-success/5 border-success/20">
          <div className="flex items-start gap-3">
            <CheckCircle className="h-5 w-5 text-success mt-0.5" />
            <div className="flex-1">
              <h3 className="font-semibold text-success mb-2">Dati Estratti Automaticamente</h3>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3 text-sm">
                <div>
                  <span className="text-muted-foreground">Corso ID:</span>
                  <span className="ml-2 font-medium text-foreground">{extractedData.corso?.id}</span>
                </div>
                <div>
                  <span className="text-muted-foreground">Titolo:</span>
                  <span className="ml-2 font-medium text-foreground">{extractedData.corso?.titolo}</span>
                </div>
                <div>
                  <span className="text-muted-foreground">Date:</span>
                  <span className="ml-2 font-medium text-foreground">
                    {extractedData.corso?.data_inizio} - {extractedData.corso?.data_fine}
                  </span>
                </div>
                <div>
                  <span className="text-muted-foreground">Partecipanti:</span>
                  <span className="ml-2 font-medium text-foreground">{extractedData.partecipanti?.length || 0}</span>
                </div>
              </div>
            </div>
          </div>
        </Card>

        <form onSubmit={handleSubmit} className="space-y-6">
          <Accordion type="single" collapsible defaultValue="staff" className="space-y-4">
            {/* Staff Section */}
            <AccordionItem value="staff" className="border rounded-lg px-4">
              <AccordionTrigger className="hover:no-underline">
                <div className="flex items-center gap-3">
                  <User className="h-5 w-5 text-primary" />
                  <span className="font-semibold">Dati Anagrafici Staff</span>
                </div>
              </AccordionTrigger>
              <AccordionContent className="space-y-4 pt-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="direttore">Direttore del Corso *</Label>
                    <Input
                      id="direttore"
                      value={formData.direttore}
                      onChange={(e) => updateField("direttore", e.target.value)}
                      placeholder="Nome completo"
                      required
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="supervisore">Supervisore</Label>
                    <Input
                      id="supervisore"
                      value={formData.supervisore}
                      onChange={(e) => updateField("supervisore", e.target.value)}
                      placeholder="Nome completo"
                    />
                  </div>
                </div>

                <div className="pt-4 border-t">
                  <h4 className="text-sm font-semibold mb-3 text-foreground">Responsabile Certificazione</h4>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="resp_nome">Nome *</Label>
                      <Input
                        id="resp_nome"
                        value={formData.responsabile_nome}
                        onChange={(e) => updateField("responsabile_nome", e.target.value)}
                        required
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="resp_cognome">Cognome *</Label>
                      <Input
                        id="resp_cognome"
                        value={formData.responsabile_cognome}
                        onChange={(e) => updateField("responsabile_cognome", e.target.value)}
                        required
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="resp_cf">Codice Fiscale</Label>
                      <Input
                        id="resp_cf"
                        value={formData.responsabile_cf}
                        onChange={(e) => updateField("responsabile_cf", e.target.value.toUpperCase())}
                        placeholder="RSSMRA80A01H501Z"
                        maxLength={16}
                      />
                    </div>
                  </div>
                </div>
              </AccordionContent>
            </AccordionItem>

            {/* Sede Section */}
            <AccordionItem value="sede" className="border rounded-lg px-4">
              <AccordionTrigger className="hover:no-underline">
                <div className="flex items-center gap-3">
                  <Calendar className="h-5 w-5 text-accent" />
                  <span className="font-semibold">Ente e Sede</span>
                </div>
              </AccordionTrigger>
              <AccordionContent className="space-y-4 pt-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="ente">Ente Accreditato</Label>
                    <Input
                      id="ente"
                      value={formData.ente_accreditato}
                      onChange={(e) => updateField("ente_accreditato", e.target.value)}
                      placeholder="Nome ente"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="sede_ente">Sede Ente</Label>
                    <Input
                      id="sede_ente"
                      value={formData.sede_ente}
                      onChange={(e) => updateField("sede_ente", e.target.value)}
                      placeholder="Indirizzo completo"
                    />
                  </div>
                </div>
              </AccordionContent>
            </AccordionItem>

            {/* Didattica Section */}
            <AccordionItem value="didattica" className="border rounded-lg px-4">
              <AccordionTrigger className="hover:no-underline">
                <div className="flex items-center gap-3">
                  <FileText className="h-5 w-5 text-success" />
                  <span className="font-semibold">Contenuti Didattici</span>
                </div>
              </AccordionTrigger>
              <AccordionContent className="space-y-4 pt-4">
                <div className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="argomenti_1">Argomenti Lezione 1 (09:00-13:00)</Label>
                    <Textarea
                      id="argomenti_1"
                      value={formData.argomenti_lezione_1}
                      onChange={(e) => updateField("argomenti_lezione_1", e.target.value)}
                      placeholder="Descrivi gli argomenti trattati..."
                      rows={3}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="argomenti_2">Argomenti Lezione 2 (14:00-18:00)</Label>
                    <Textarea
                      id="argomenti_2"
                      value={formData.argomenti_lezione_2}
                      onChange={(e) => updateField("argomenti_lezione_2", e.target.value)}
                      placeholder="Descrivi gli argomenti trattati..."
                      rows={3}
                    />
                  </div>
                </div>
              </AccordionContent>
            </AccordionItem>
          </Accordion>

          <div className="flex justify-end pt-6 border-t">
            <Button
              type="submit"
              size="lg"
              className="bg-gradient-to-r from-primary to-accent hover:opacity-90"
            >
              Genera Documenti
              <ArrowRight className="ml-2 h-5 w-5" />
            </Button>
          </div>
        </form>
      </div>
    </Card>
  );
};

export default CompletionStep;

/**
 * Data Preview & Edit Step
 *
 * Purpose: Review and edit extracted data before document generation
 * - Visual preview of all extracted fields
 * - Inline editing capabilities
 * - Validation warnings and errors
 * - Export/Import JSON
 * - Auto-save functionality
 */

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import {
  CheckCircle2,
  AlertTriangle,
  XCircle,
  Download,
  Upload,
  FileJson,
  Copy,
  Eye,
  EyeOff,
} from 'lucide-react';
import { toast } from 'sonner';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import {
  exportDataAsJSON,
  importDataFromJSON,
  autoSaveData,
  loadAutoSavedData,
  clearAutoSavedData,
} from '@/services/jsonExportImportService';

// ============================================================================
// TYPES
// ============================================================================

interface DataPreviewStepProps {
  data: any;
  onDataChange: (updatedData: any) => void;
  onContinue: () => void;
  onBack?: () => void;
}

interface ValidationIssue {
  field: string;
  type: 'error' | 'warning' | 'info';
  message: string;
}

// ============================================================================
// COMPONENT
// ============================================================================

const DataPreviewStep = ({
  data,
  onDataChange,
  onContinue,
  onBack,
}: DataPreviewStepProps) => {
  const [editedData, setEditedData] = useState(data);
  const [showRawJSON, setShowRawJSON] = useState(false);
  const [validationIssues, setValidationIssues] = useState<ValidationIssue[]>([]);
  const [lastSaveTime, setLastSaveTime] = useState<Date>(new Date());

  // Auto-save on data change
  useEffect(() => {
    autoSaveData(editedData);
    setLastSaveTime(new Date());
  }, [editedData]);

  // Validate data on mount and when data changes
  useEffect(() => {
    const issues = validateData(editedData);
    setValidationIssues(issues);
  }, [editedData]);

  /**
   * Validates data and returns issues
   */
  const validateData = (dataToValidate: any): ValidationIssue[] => {
    const issues: ValidationIssue[] = [];

    // Check corso
    if (!dataToValidate.corso?.id) {
      issues.push({
        field: 'corso.id',
        type: 'error',
        message: 'ID Corso mancante',
      });
    }

    if (!dataToValidate.corso?.titolo) {
      issues.push({
        field: 'corso.titolo',
        type: 'warning',
        message: 'Titolo corso mancante',
      });
    }

    // Check partecipanti
    if (!dataToValidate.partecipanti || dataToValidate.partecipanti.length === 0) {
      issues.push({
        field: 'partecipanti',
        type: 'error',
        message: 'Nessun partecipante trovato',
      });
    } else {
      // Check for invalid codici fiscali
      dataToValidate.partecipanti.forEach((p: any, idx: number) => {
        if (p._validations && !p._validations.cf_valid) {
          issues.push({
            field: `partecipanti[${idx}].codice_fiscale`,
            type: 'warning',
            message: `CF non valido: ${p.nome} ${p.cognome}`,
          });
        }
      });
    }

    // Check sessioni
    if (!dataToValidate.sessioni || dataToValidate.sessioni.length === 0) {
      issues.push({
        field: 'sessioni',
        type: 'warning',
        message: 'Nessuna sessione trovata',
      });
    }

    // Check moduli
    if (dataToValidate.moduli && dataToValidate.moduli.length === 0) {
      issues.push({
        field: 'moduli',
        type: 'info',
        message: 'Nessun modulo definito',
      });
    }

    return issues;
  };

  /**
   * Handles JSON export
   */
  const handleExport = () => {
    try {
      exportDataAsJSON(editedData);
      toast.success('JSON esportato con successo!');
    } catch (error: any) {
      toast.error(error.message);
    }
  };

  /**
   * Handles JSON import
   */
  const handleImport = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    try {
      const importedData = await importDataFromJSON(file);
      setEditedData(importedData);
      onDataChange(importedData);
      toast.success('JSON importato con successo!');

      // Reset file input
      event.target.value = '';
    } catch (error: any) {
      toast.error(error.message);
    }
  };

  /**
   * Copies JSON to clipboard
   */
  const handleCopyJSON = () => {
    try {
      const jsonString = JSON.stringify(editedData, null, 2);
      navigator.clipboard.writeText(jsonString);
      toast.success('JSON copiato negli appunti!');
    } catch (error) {
      toast.error('Impossibile copiare negli appunti');
    }
  };

  // Count validation issues by type
  const errorCount = validationIssues.filter((i) => i.type === 'error').length;
  const warningCount = validationIssues.filter((i) => i.type === 'warning').length;
  const hasBlockingErrors = errorCount > 0;

  return (
    <div className="space-y-6">
      {/* Header with Actions */}
      <Card className="p-6">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h3 className="text-xl font-bold flex items-center gap-2">
              <Eye className="h-5 w-5 text-primary" />
              Anteprima e Modifica Dati
            </h3>
            <p className="text-sm text-muted-foreground mt-1">
              Verifica i dati estratti prima di generare i documenti
            </p>
          </div>

          <div className="flex gap-2">
            {/* Export JSON */}
            <Button onClick={handleExport} variant="outline" size="sm">
              <Download className="mr-2 h-4 w-4" />
              Esporta JSON
            </Button>

            {/* Import JSON */}
            <Button variant="outline" size="sm" asChild>
              <label className="cursor-pointer">
                <Upload className="mr-2 h-4 w-4" />
                Importa JSON
                <input
                  type="file"
                  accept=".json"
                  onChange={handleImport}
                  className="hidden"
                />
              </label>
            </Button>

            {/* Copy JSON */}
            <Button onClick={handleCopyJSON} variant="outline" size="sm">
              <Copy className="mr-2 h-4 w-4" />
              Copia
            </Button>

            {/* Toggle Raw JSON */}
            <Button
              onClick={() => setShowRawJSON(!showRawJSON)}
              variant="outline"
              size="sm"
            >
              {showRawJSON ? (
                <>
                  <EyeOff className="mr-2 h-4 w-4" />
                  Nascondi JSON
                </>
              ) : (
                <>
                  <FileJson className="mr-2 h-4 w-4" />
                  Mostra JSON
                </>
              )}
            </Button>
          </div>
        </div>

        {/* Validation Summary */}
        <div className="flex gap-3">
          {errorCount > 0 && (
            <Badge variant="destructive" className="gap-1">
              <XCircle className="h-3 w-3" />
              {errorCount} {errorCount === 1 ? 'Errore' : 'Errori'}
            </Badge>
          )}
          {warningCount > 0 && (
            <Badge variant="secondary" className="gap-1 bg-amber-100 text-amber-900 dark:bg-amber-900 dark:text-amber-100">
              <AlertTriangle className="h-3 w-3" />
              {warningCount} {warningCount === 1 ? 'Avviso' : 'Avvisi'}
            </Badge>
          )}
          {errorCount === 0 && warningCount === 0 && (
            <Badge variant="secondary" className="gap-1 bg-green-100 text-green-900 dark:bg-green-900 dark:text-green-100">
              <CheckCircle2 className="h-3 w-3" />
              Tutti i dati sono validi
            </Badge>
          )}
        </div>
      </Card>

      {/* Validation Issues */}
      {validationIssues.length > 0 && (
        <Card className="p-6">
          <h4 className="font-semibold mb-3">Problemi Rilevati</h4>
          <div className="space-y-2">
            {validationIssues.map((issue, idx) => (
              <div
                key={idx}
                className={`flex items-start gap-2 p-3 rounded-lg ${
                  issue.type === 'error'
                    ? 'bg-red-50 dark:bg-red-950 border border-red-200 dark:border-red-800'
                    : issue.type === 'warning'
                    ? 'bg-amber-50 dark:bg-amber-950 border border-amber-200 dark:border-amber-800'
                    : 'bg-blue-50 dark:bg-blue-950 border border-blue-200 dark:border-blue-800'
                }`}
              >
                {issue.type === 'error' && <XCircle className="h-4 w-4 text-red-600 flex-shrink-0 mt-0.5" />}
                {issue.type === 'warning' && <AlertTriangle className="h-4 w-4 text-amber-600 flex-shrink-0 mt-0.5" />}
                {issue.type === 'info' && <CheckCircle2 className="h-4 w-4 text-blue-600 flex-shrink-0 mt-0.5" />}
                <div className="flex-1">
                  <p className="text-sm font-medium">{issue.message}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">Campo: {issue.field}</p>
                </div>
              </div>
            ))}
          </div>
        </Card>
      )}

      {/* Raw JSON View */}
      {showRawJSON && (
        <Card className="p-6">
          <div className="flex items-center justify-between mb-3">
            <h4 className="font-semibold">JSON Completo</h4>
            <Button onClick={handleCopyJSON} variant="outline" size="sm">
              <Copy className="mr-2 h-3 w-3" />
              Copia
            </Button>
          </div>
          <pre className="bg-muted p-4 rounded-lg overflow-auto max-h-96 text-xs font-mono">
            {JSON.stringify(editedData, null, 2)}
          </pre>
        </Card>
      )}

      {/* Data Sections (Accordion) */}
      <Card className="p-6">
        <Accordion type="multiple" defaultValue={['corso', 'partecipanti']} className="w-full">
          {/* Corso */}
          <AccordionItem value="corso">
            <AccordionTrigger>
              <div className="flex items-center gap-2">
                <span className="font-semibold">Corso</span>
                {editedData.corso?.id && (
                  <Badge variant="outline">{editedData.corso.id}</Badge>
                )}
              </div>
            </AccordionTrigger>
            <AccordionContent>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 p-4">
                <div>
                  <Label className="text-xs text-muted-foreground">ID Corso</Label>
                  <p className="font-medium">{editedData.corso?.id || 'N/A'}</p>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">Titolo</Label>
                  <p className="font-medium">{editedData.corso?.titolo || 'N/A'}</p>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">Data Inizio</Label>
                  <p className="font-medium">{editedData.corso?.data_inizio || 'N/A'}</p>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">Data Fine</Label>
                  <p className="font-medium">{editedData.corso?.data_fine || 'N/A'}</p>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">Ore Totali</Label>
                  <p className="font-medium">{editedData.corso?.ore_totali || 'N/A'}</p>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">Stato</Label>
                  <p className="font-medium">{editedData.corso?.stato || 'N/A'}</p>
                </div>
              </div>
            </AccordionContent>
          </AccordionItem>

          {/* Partecipanti */}
          <AccordionItem value="partecipanti">
            <AccordionTrigger>
              <div className="flex items-center gap-2">
                <span className="font-semibold">Partecipanti</span>
                <Badge variant="outline">
                  {editedData.partecipanti?.length || 0}
                </Badge>
              </div>
            </AccordionTrigger>
            <AccordionContent>
              <div className="space-y-2 p-4">
                {editedData.partecipanti?.map((p: any, idx: number) => (
                  <div key={idx} className="p-3 border rounded-lg">
                    <div className="flex items-center justify-between mb-2">
                      <p className="font-medium">
                        {p.numero}. {p.nome_completo}
                      </p>
                      {p._validations && (
                        <div className="flex gap-1">
                          {p._validations.cf_valid ? (
                            <Badge variant="outline" className="text-xs gap-1">
                              <CheckCircle2 className="h-3 w-3" />
                              CF
                            </Badge>
                          ) : (
                            <Badge variant="destructive" className="text-xs gap-1">
                              <XCircle className="h-3 w-3" />
                              CF
                            </Badge>
                          )}
                        </div>
                      )}
                    </div>
                    <div className="grid grid-cols-2 gap-2 text-xs">
                      <div>
                        <span className="text-muted-foreground">CF:</span>{' '}
                        {p.codice_fiscale || 'N/A'}
                      </div>
                      <div>
                        <span className="text-muted-foreground">Email:</span>{' '}
                        {p.email || 'N/A'}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </AccordionContent>
          </AccordionItem>

          {/* Sessioni */}
          <AccordionItem value="sessioni">
            <AccordionTrigger>
              <div className="flex items-center gap-2">
                <span className="font-semibold">Sessioni</span>
                <Badge variant="outline">
                  {editedData.sessioni?.length || 0}
                </Badge>
              </div>
            </AccordionTrigger>
            <AccordionContent>
              <div className="space-y-2 p-4">
                {editedData.sessioni?.map((s: any, idx: number) => (
                  <div key={idx} className="p-3 border rounded-lg">
                    <div className="flex items-center justify-between">
                      <div>
                        <p className="font-medium">{s.data_completa}</p>
                        <p className="text-sm text-muted-foreground">
                          {s.ora_inizio_giornata} - {s.ora_fine_giornata}
                        </p>
                      </div>
                      <div className="flex gap-2">
                        <Badge variant={s.is_fad ? 'secondary' : 'default'}>
                          {s.is_fad ? 'FAD' : 'Presenza'}
                        </Badge>
                        <Badge variant="outline">{s.sede}</Badge>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </AccordionContent>
          </AccordionItem>

          {/* Metadata */}
          <AccordionItem value="metadata">
            <AccordionTrigger>
              <div className="flex items-center gap-2">
                <span className="font-semibold">Metadati Estrazione</span>
                {editedData.metadata?.completamento_percentuale && (
                  <Badge variant="outline">
                    {editedData.metadata.completamento_percentuale}% completo
                  </Badge>
                )}
              </div>
            </AccordionTrigger>
            <AccordionContent>
              <div className="space-y-3 p-4">
                <div>
                  <Label className="text-xs text-muted-foreground">Data Estrazione</Label>
                  <p className="text-sm">
                    {editedData.metadata?.data_estrazione
                      ? new Date(editedData.metadata.data_estrazione).toLocaleString('it-IT')
                      : 'N/A'}
                  </p>
                </div>
                <div>
                  <Label className="text-xs text-muted-foreground">Versione Sistema</Label>
                  <p className="text-sm">{editedData.metadata?.versione_sistema || 'N/A'}</p>
                </div>
                {editedData.metadata?.warnings && editedData.metadata.warnings.length > 0 && (
                  <div>
                    <Label className="text-xs text-muted-foreground">Avvisi Estrazione</Label>
                    <ul className="text-sm space-y-1 mt-1">
                      {editedData.metadata.warnings.map((w: string, idx: number) => (
                        <li key={idx} className="text-amber-700 dark:text-amber-400">
                          • {w}
                        </li>
                      ))}
                    </ul>
                  </div>
                )}
              </div>
            </AccordionContent>
          </AccordionItem>
        </Accordion>
      </Card>

      {/* Action Buttons */}
      <div className="flex gap-3">
        {onBack && (
          <Button onClick={onBack} variant="outline">
            Indietro
          </Button>
        )}
        <Button
          onClick={onContinue}
          disabled={hasBlockingErrors}
          className="flex-1 bg-gradient-to-r from-primary to-accent"
        >
          {hasBlockingErrors ? (
            <>
              <XCircle className="mr-2 h-4 w-4" />
              Correggi errori per continuare
            </>
          ) : (
            <>
              <CheckCircle2 className="mr-2 h-4 w-4" />
              Genera Documenti
            </>
          )}
        </Button>
      </div>

      {/* Auto-save Indicator */}
      <p className="text-xs text-center text-muted-foreground">
        💾 Salvataggio automatico attivo • Ultima modifica:{' '}
        {lastSaveTime.toLocaleTimeString('it-IT')}
      </p>
    </div>
  );
};

