const Toggle = React.forwardRef<
  React.ElementRef<typeof TogglePrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof TogglePrimitive.Root> &
  VariantProps<typeof toggleVariants>
>(({ className, variant, size, ...props }, ref) => (
  <TogglePrimitive.Root
    ref={ref}
    className={cn(toggleVariants({ variant, size, className }))}
    {...props}
  />
))

Toggle.displayName = TogglePrimitive.Root.displayName

export { Toggle, toggleVariants }

/**
 * Complete Workflow Example with All New Features
 *
 * Purpose: Demonstrates the full user journey with all UX improvements
 * - Input → Extract → Preview → Edit → Export/Import → Generate
 */

import { useState } from 'react';
import { toast } from 'sonner';
import InputStepWizard from '@/components/steps/InputStepWizard';
import AdditionalDataStep from '@/components/steps/AdditionalDataStep';
import DataPreviewStep from '@/components/steps/DataPreviewStep';
import ErrorBoundary from '@/components/ErrorBoundary';
import { extractCourseDataWithGemini } from '@/services/geminiService';
import { getStoredApiKey } from '@/utils/apiKeyUtils';
import {
  exportDataAsJSON,
  loadAutoSavedData,
  hasAutoSavedData,
  clearAutoSavedData,
} from '@/services/jsonExportImportService';
import { validateAndNormalizeData } from '@/utils/robustHelpers';
import { generateExcelFromTemplate } from '@/services/excelTemplateGenerator';
import { PREDEFINED_TEMPLATES } from '@/types/templateConfig';

// ============================================================================
// WORKFLOW STEPS
// ============================================================================

enum WorkflowStep {
  INPUT = 'input',           // Collect course data from gestionale
  ADDITIONAL = 'additional', // Collect CF docente, Zoom link
  PREVIEW = 'preview',       // Preview and validate extracted data
  GENERATION = 'generation', // Generate documents
  COMPLETE = 'complete',     // Download & finish
}

// ============================================================================
// MAIN COMPONENT
// ============================================================================

const CompleteWorkflowExample = () => {
  const [currentStep, setCurrentStep] = useState<WorkflowStep>(WorkflowStep.INPUT);
  const [extractedData, setExtractedData] = useState<any>(null);
  const [additionalData, setAdditionalData] = useState<any>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  /**
   * Check for auto-saved data on mount
   */
  useState(() => {
    if (hasAutoSavedData()) {
      const autoSaved = loadAutoSavedData();
      if (autoSaved) {
        toast.info('Dati trovati in memoria!', {
          description: `Salvati: ${new Date(autoSaved.savedAt).toLocaleString('it-IT')}`,
          action: {
            label: 'Ripristina',
            onClick: () => handleRestoreAutoSave(autoSaved.data),
          },
          duration: 10000, // Show for 10 seconds
        });
      }
    }
  });

  /**
   * Handles restore from auto-save
   */
  const handleRestoreAutoSave = (data: any) => {
    setExtractedData(data);
    setCurrentStep(WorkflowStep.PREVIEW);
    toast.success('Dati ripristinati!');
  };

  /**
   * STEP 1: Input - User pastes data from gestionale
   */
  const handleInputComplete = async (rawData: any) => {
    setIsProcessing(true);

    try {
      const apiKey = getStoredApiKey();
      if (!apiKey) {
        toast.error('Configura prima la chiave API Gemini');
        setIsProcessing(false);
        return;
      }

      // Extract data with AI
      toast.info('Estrazione dati in corso...');
      const extracted = await extractCourseDataWithGemini(
        apiKey,
        rawData.courseData,
        rawData.modulesData,
        rawData.participantsData
      );

      // Validate and normalize
      const { normalizedData, warnings, errors } = validateAndNormalizeData(extracted);

      if (errors.length > 0) {
        toast.warning('Dati estratti con errori', {
          description: `${errors.length} errori trovati. Potrai correggerli nel prossimo step.`,
        });
      }

      if (warnings.length > 0) {
        toast.info(`${warnings.length} avvisi rilevati`, {
          description: 'Verifica i dati nella schermata di anteprima',
        });
      }

      setExtractedData(normalizedData);
      setCurrentStep(WorkflowStep.ADDITIONAL);
      toast.success('Dati estratti con successo!');
    } catch (error: any) {
      console.error('Extraction error:', error);
      toast.error('Errore durante l\'estrazione', {
        description: error.message,
        action: {
          label: 'Riprova',
          onClick: () => handleInputComplete(rawData),
        },
      });
    } finally {
      setIsProcessing(false);
    }
  };

  /**
   * STEP 2: Additional Data - Collect CF docente, Zoom link
   */
  const handleAdditionalDataComplete = (data: any) => {
    setAdditionalData(data);

    // Merge additional data into extracted data
    const mergedData = {
      ...extractedData,
      codice_fiscale_docente: data.codiceFiscaleDocente,
      link_zoom: data.linkZoom,
      note: data.note,
    };

    setExtractedData(mergedData);
    setCurrentStep(WorkflowStep.PREVIEW);
    toast.success('Dati aggiuntivi salvati!');
  };

  /**
   * STEP 3: Preview - Review and edit data
   */
  const handlePreviewContinue = () => {
    // Final validation before generation
    const { errors } = validateAndNormalizeData(extractedData);

    if (errors.length > 0) {
      toast.error('Correggi gli errori prima di continuare', {
        description: errors.join(', '),
      });
      return;
    }

    // Offer to export JSON before generation
    toast.info('Vuoi salvare un backup prima di generare?', {
      action: {
        label: 'Esporta JSON',
        onClick: () => {
          exportDataAsJSON(extractedData);
          toast.success('Backup creato!');
        },
      },
      duration: 5000,
    });

    setCurrentStep(WorkflowStep.GENERATION);
  };

  /**
   * STEP 4: Generation - Generate documents
   */
  const handleGeneration = async () => {
    setIsProcessing(true);

    try {
      toast.info('Generazione documenti in corso...');

      // Generate Excel with template
      const templateConfig = {
        ...PREDEFINED_TEMPLATES.REGISTRO_ORE,
        id: 'registro_1',
        version: '1.0.0',
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };

      generateExcelFromTemplate(extractedData, templateConfig);

      // TODO: Generate Word documents

      // TODO: Create ZIP package

      setCurrentStep(WorkflowStep.COMPLETE);
      toast.success('Documenti generati con successo!');

      // Clear auto-save after successful generation
      clearAutoSavedData();
    } catch (error: any) {
      console.error('Generation error:', error);
      toast.error('Errore durante la generazione', {
        description: error.message,
        action: {
          label: 'Riprova',
          onClick: handleGeneration,
        },
      });
    } finally {
      setIsProcessing(false);
    }
  };

  /**
   * STEP 5: Complete - Show success and options
   */
  const handleStartOver = () => {
    setExtractedData(null);
    setAdditionalData(null);
    setCurrentStep(WorkflowStep.INPUT);
    clearAutoSavedData();
    toast.info('Workflow riavviato');
  };

  // ========================================================================
  // RENDER
  // ========================================================================

  return (
    <ErrorBoundary>
      <div className="container max-w-4xl mx-auto py-8 px-4">
        {/* Progress Indicator */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            {Object.values(WorkflowStep).map((step, idx) => {
              const isCurrent = step === currentStep;
              const isComplete = Object.values(WorkflowStep).indexOf(currentStep) > idx;

              return (
                <div key={step} className="flex items-center">
                  <div
                    className={`w-10 h-10 rounded-full flex items-center justify-center font-bold ${isCurrent
                        ? 'bg-primary text-primary-foreground'
                        : isComplete
                          ? 'bg-green-500 text-white'
                          : 'bg-muted text-muted-foreground'
                      }`}
                  >
                    {isComplete ? '✓' : idx + 1}
                  </div>
                  {idx < Object.values(WorkflowStep).length - 1 && (
                    <div
                      className={`h-1 w-16 mx-2 ${isComplete ? 'bg-green-500' : 'bg-muted'
                        }`}
                    />
                  )}
                </div>
              );
            })}
          </div>
          <div className="flex justify-between mt-2">
            <span className="text-xs text-muted-foreground">Input</span>
            <span className="text-xs text-muted-foreground">Dati Extra</span>
            <span className="text-xs text-muted-foreground">Anteprima</span>
            <span className="text-xs text-muted-foreground">Genera</span>
            <span className="text-xs text-muted-foreground">Completo</span>
          </div>
        </div>

        {/* Step Content */}
        <div>
          {currentStep === WorkflowStep.INPUT && (
            <InputStepWizard onComplete={handleInputComplete} />
          )}

          {currentStep === WorkflowStep.ADDITIONAL && (
            <AdditionalDataStep
              onComplete={handleAdditionalDataComplete}
              onBack={() => setCurrentStep(WorkflowStep.INPUT)}
            />
          )}

          {currentStep === WorkflowStep.PREVIEW && extractedData && (
            <DataPreviewStep
              data={extractedData}
              onDataChange={setExtractedData}
              onContinue={handlePreviewContinue}
              onBack={() => setCurrentStep(WorkflowStep.ADDITIONAL)}
            />
          )}

          {currentStep === WorkflowStep.GENERATION && (
            <div className="text-center space-y-6">
              <h2 className="text-2xl font-bold">Generazione Documenti</h2>
              <p className="text-muted-foreground">
                Pronto per generare tutti i documenti?
              </p>
              <div className="flex gap-4 justify-center">
                <button
                  onClick={() => setCurrentStep(WorkflowStep.PREVIEW)}
                  disabled={isProcessing}
                  className="px-6 py-3 border rounded-lg hover:bg-muted"
                >
                  Indietro
                </button>
                <button
                  onClick={handleGeneration}
                  disabled={isProcessing}
                  className="px-6 py-3 bg-primary text-primary-foreground rounded-lg hover:opacity-90"
                >
                  {isProcessing ? 'Generazione...' : 'Genera Tutti i Documenti'}
                </button>
              </div>
            </div>
          )}

          {currentStep === WorkflowStep.COMPLETE && (
            <div className="text-center space-y-6">
              <div className="text-6xl">🎉</div>
              <h2 className="text-2xl font-bold">Completato!</h2>
              <p className="text-muted-foreground">
                Tutti i documenti sono stati generati e scaricati
              </p>
              <div className="flex gap-4 justify-center">
                <button
                  onClick={handleStartOver}
                  className="px-6 py-3 border rounded-lg hover:bg-muted"
                >
                  Nuovo Corso
                </button>
                <button
                  onClick={() => exportDataAsJSON(extractedData)}
                  className="px-6 py-3 bg-primary text-primary-foreground rounded-lg hover:opacity-90"
                >
                  Scarica Backup JSON
                </button>
              </div>
            </div>
          )}
        </div>

        {/* Debug Panel (Development only) */}
        {process.env.NODE_ENV === 'development' && (
          <div className="mt-8 p-4 bg-muted rounded-lg">
            <details>
              <summary className="cursor-pointer font-medium mb-2">
                🐛 Debug Info
              </summary>
              <pre className="text-xs overflow-auto max-h-60">
                {JSON.stringify(
                  {
                    currentStep,
                    hasExtractedData: !!extractedData,
                    hasAdditionalData: !!additionalData,
                    isProcessing,
                  },
                  null,
                  2
                )}
              </pre>
            </details>
          </div>
        )}
      </div>
    </ErrorBoundary>
  );
};

export default CompleteWorkflowExample;

import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { onAuthStateChange, getSession, signIn } from "@/services/localAuth";
import type { LocalUser } from "@/services/localDb";

export const useAuth = () => {
  const [user, setUser] = useState<LocalUser | null>(null);
  const [session, setSession] = useState<{ user: LocalUser } | null>(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const subscription = onAuthStateChange((event, sessionUser) => {
      setSession(sessionUser ? { user: sessionUser } : null);
      setUser(sessionUser ?? null);
      if (event === "SIGNED_IN") {
        setTimeout(() => navigate("/"), 50);
      } else if (event === "SIGNED_OUT") {
        setTimeout(() => navigate("/auth"), 50);
      }
    });

    getSession().then(async ({ data: { session } }) => {
      if (!session) {
        const { user: defaultUser } = await signIn("offline@local");
        setSession(defaultUser ? { user: defaultUser } : null);
        setUser(defaultUser ?? null);
      } else {
        setSession(session as any);
        setUser(session?.user ?? null);
      }
      setLoading(false);
    });

    return () => subscription.unsubscribe();
  }, [navigate]);

  return { user, session, loading };
};

/**
 * useCompletionData Hook
 *
 * Purpose: Manages data loading and state for the Completion Step
 * Clean Code Principle: Separation of Concerns - Data fetching logic isolated from UI
 */

import { useState, useEffect, useCallback } from "react";
import { toast } from "sonner";
import type { CourseData, EnteAccreditato, ResponsabileCorso } from "@/types/courseData";
import { getEnabledEntities, getEnabledResponsabili, getEnabledSupervisors, getEnabledLocations } from "@/utils/predefinedDataUtils";
import { listEnti, listResponsabili } from "@/services/localDb";

export const useCompletionData = (
    initialData: CourseData,
    onComplete: (data: CourseData) => void
) => {
    // Form State
    const [formData, setFormData] = useState<CourseData>(initialData);

    // Database Data State
    const [enti, setEnti] = useState<EnteAccreditato[]>([]);
    const [direttori, setDirettori] = useState<ResponsabileCorso[]>([]);
    const [supervisori, setSupervisori] = useState<ResponsabileCorso[]>([]);
    const [responsabiliCert, setResponsabiliCert] = useState<ResponsabileCorso[]>([]);
    const [loading, setLoading] = useState(true);
    const trainerFullName =
        `${formData.trainer?.nome || ''} ${formData.trainer?.cognome || ''}`.trim() ||
        formData.trainer?.nome_completo ||
        '';



    const applyFallbackData = useCallback((message?: string) => {
        const fallbackEnti: EnteAccreditato[] = getEnabledEntities().map(entity => ({
            id: `local-ente-${entity.id}`,
            nome: entity.name,
            via: entity.address,
            numero_civico: "",
            comune: "",
            cap: "",
            provincia: ""
        }));

        const supervisors = getEnabledSupervisors();
        const fallbackDirettori: ResponsabileCorso[] = supervisors.map(sup => {
            return {
                id: `local-dir-${sup.id}`,
                tipo: "direttore",
                nome: sup.nome,
                cognome: sup.cognome,
                qualifica: sup.qualifica
            };
        });

        const fallbackSupervisori: ResponsabileCorso[] = supervisors.map(sup => {
            return {
                id: `local-sup-${sup.id}`,
                tipo: "supervisore",
                nome: sup.nome,
                cognome: sup.cognome,
                qualifica: sup.qualifica
            };
        });

        const fallbackResponsabili: ResponsabileCorso[] = getEnabledResponsabili().map(resp => ({
            id: `local-resp-${resp.id}`,
            tipo: "responsabile_cert",
            nome: resp.nome,
            cognome: resp.cognome,
            qualifica: "Responsabile Certificazione",
            data_nascita: resp.dataNascita,
            citta_nascita: resp.cittaNascita,
            provincia_nascita: resp.provinciaNascita,
            citta_residenza: resp.cittaResidenza,
            via_residenza: resp.viaResidenza,
            numero_civico_residenza: resp.numeroCivico,
            documento_identita: resp.documento
        }));

        if (fallbackEnti.length || fallbackDirettori.length || fallbackSupervisori.length || fallbackResponsabili.length) {
            setEnti(fallbackEnti);
            setDirettori(fallbackDirettori);
            setSupervisori(fallbackSupervisori);
            setResponsabiliCert(fallbackResponsabili);
            if (message) {
                toast.info(message);
            }
        }
    }, []);

    const loadData = useCallback(async () => {
        try {
            const [entiData, responsabiliData] = await Promise.all([
                listEnti(),
                listResponsabili()
            ]);

            // Include Locations as Entities to support selection from Step 2
            const locationsAsEntities: EnteAccreditato[] = getEnabledLocations().map(loc => ({
                id: loc.id,
                nome: loc.name,
                via: loc.address,
                numero_civico: "",
                comune: "",
                cap: "",
                provincia: ""
            }));

            // Merge unique entities (prefer real entities over locations if ID conflicts, though unlikely)
            const allEnti = [...(entiData || []), ...locationsAsEntities];
            // Remove duplicates by ID
            const uniqueEnti = Array.from(new Map(allEnti.map(item => [item.id, item])).values());

            setEnti(uniqueEnti);

            const typedResponsabili = (responsabiliData || []).map(r => ({
                ...r,
                tipo: r.tipo as 'direttore' | 'supervisore' | 'responsabile_cert'
            }));

            setDirettori(typedResponsabili.filter(r => r.tipo === 'direttore'));
            setSupervisori(typedResponsabili.filter(r => r.tipo === 'supervisore'));
            setResponsabiliCert(typedResponsabili.filter(r => r.tipo === 'responsabile_cert'));

            if ((entiData?.length || 0) === 0 && (responsabiliData?.length || 0) === 0) {
                applyFallbackData("Nessun dato salvato: uso i valori predefiniti salvati in locale.");
            }
        } catch (error: any) {
            console.error("Error loading data:", error);
            toast.error("Errore caricamento dati: " + error.message);
            applyFallbackData("Errore nel recupero dei dati locali: uso i dati predefiniti salvati in locale.");
        } finally {
            setLoading(false);
        }
    }, [applyFallbackData]);

    // Load data on mount
    useEffect(() => {
        loadData();
    }, [loadData]);

    // Auto-select direttore using the trainer info when possible
    useEffect(() => {
        if (!trainerFullName || formData.direttore_id || direttori.length === 0) return;

        const normalizedTrainer = trainerFullName.toLowerCase();
        const match = direttori.find((dir) =>
            `${dir.nome || ''} ${dir.cognome || ''}`.toLowerCase().trim() === normalizedTrainer ||
            (dir.nome && dir.nome.toLowerCase() === normalizedTrainer) ||
            (dir.cognome && dir.cognome.toLowerCase() === normalizedTrainer)
        );

        if (match) {
            setFormData((prev) => ({ ...prev, direttore_id: match.id }));
        }
    }, [trainerFullName, formData.direttore_id, direttori]);

    const updateFormData = (key: keyof CourseData | Partial<CourseData>, value?: any) => {
        if (typeof key === 'string') {
            setFormData(prev => ({ ...prev, [key]: value }));
        } else {
            setFormData(prev => ({ ...prev, ...key }));
        }
    };

    const validateAndSubmit = () => {
        if (enti.length > 0 && !formData.ente_accreditato_id) {
            toast.error("Seleziona un Ente Accreditato");
            return;
        }

        if (direttori.length > 0 && !formData.direttore_id) {
            toast.error("Seleziona un Direttore");
            return;
        }

        if (supervisori.length > 0 && !formData.supervisore_id) {
            toast.error("Seleziona un Supervisore");
            return;
        }

        const updatedData: CourseData = { ...formData };

        // Applica l'ente accreditato selezionato ai dati corso
        if (formData.ente_accreditato_id) {
            const ente = enti.find(e => e.id === formData.ente_accreditato_id);
            if (ente) {
                updatedData.ente = {
                    ...formData.ente,
                    id: ente.id,
                    nome: ente.nome,
                    indirizzo: [ente.via, ente.numero_civico, ente.comune, ente.provincia].filter(Boolean).join(" "),
                    accreditato: {
                        nome: ente.nome,
                        via: ente.via,
                        numero_civico: ente.numero_civico,
                        comune: ente.comune,
                        cap: ente.cap,
                        provincia: ente.provincia
                    }
                };
            }
        }

        toast.success("Dati completati! Procedi con la generazione documenti");
        onComplete(updatedData);
    };

    return {
        formData,
        enti,
        direttori,
        supervisori,
        responsabiliCert,
        loading,
        updateFormData,
        validateAndSubmit
    };
};

/**
 * useWizardState Hook
 *
 * Purpose: Manages the state and logic for the InputStepWizard component
 * Clean Code Principle: Separation of Concerns - Logic separated from UI
 */

import { useState } from 'react';
import { toast } from 'sonner';
import {
    WIZARD_CONFIG,
    VALIDATION_MESSAGES,
    SUCCESS_MESSAGES,
    API_KEY_MESSAGES,
    EXTRACTION_MESSAGES,
    WARNING_MESSAGES
} from '@/constants/wizardConstants';
import { WIZARD_EXAMPLES } from '@/constants/examples';
import { getStoredApiKey } from '@/utils/apiKeyUtils';
import { extractCourseDataWithGemini, extractCourseDataWithDoubleCheck } from '@/services/geminiService';

export const useWizardState = (onComplete: (data: any) => void) => {
    // State
    const [currentSubStep, setCurrentSubStep] = useState<number>(WIZARD_CONFIG.FIRST_STEP);
    const [courseData, setCourseData] = useState("");
    const [modulesData, setModulesData] = useState("");
    const [participantsData, setParticipantsData] = useState("");
    const [isProcessing, setIsProcessing] = useState(false);
    const [useDoubleCheck, setUseDoubleCheck] = useState(true);
    const [progressMessage, setProgressMessage] = useState("");
    const [progressPercent, setProgressPercent] = useState(0);

    // Validation
    const validateStepData = (step: number): boolean => {
        if (step === 1 && !courseData.trim()) {
            toast.error(VALIDATION_MESSAGES.COURSE_EMPTY);
            return false;
        }
        if (step === 2 && !modulesData.trim()) {
            toast.error(VALIDATION_MESSAGES.MODULES_EMPTY);
            return false;
        }
        if (step === 3 && !participantsData.trim()) {
            toast.error(VALIDATION_MESSAGES.PARTICIPANTS_EMPTY);
            return false;
        }
        return true;
    };

    // Navigation
    const handleNext = () => {
        if (!validateStepData(currentSubStep)) return;

        if (currentSubStep < WIZARD_CONFIG.LAST_STEP) {
            setCurrentSubStep(currentSubStep + 1);
            toast.success(SUCCESS_MESSAGES.STEP_COMPLETED(currentSubStep));
        }
    };

    const handleBack = () => {
        if (currentSubStep > WIZARD_CONFIG.FIRST_STEP) {
            setCurrentSubStep(currentSubStep - 1);
        }
    };

    // Actions
    const handlePasteExample = (step: number) => {
        if (step === 1) setCourseData(WIZARD_EXAMPLES[1]);
        if (step === 2) setModulesData(WIZARD_EXAMPLES[2]);
        if (step === 3) setParticipantsData(WIZARD_EXAMPLES[3]);
        toast.success(SUCCESS_MESSAGES.EXAMPLE_LOADED);
    };

    const handleExtraction = async () => {
        // 1. Validate all steps
        if (!courseData.trim() || !modulesData.trim() || !participantsData.trim()) {
            toast.error(VALIDATION_MESSAGES.ALL_STEPS_REQUIRED);
            return;
        }

        // 2. Check API Key
        const apiKey = getStoredApiKey();
        if (!apiKey) {
            toast.error(API_KEY_MESSAGES.MISSING, {
                description: API_KEY_MESSAGES.MISSING_DESCRIPTION,
                action: {
                    label: API_KEY_MESSAGES.CONFIGURE_BUTTON,
                    onClick: () => document.querySelector<HTMLElement>('[data-trigger="settings"]')?.click(),
                },
            });
            return;
        }

        setIsProcessing(true);
        setProgressPercent(0);

        try {
            let result;

            if (useDoubleCheck) {
                // Double Check Extraction
                setProgressMessage("Avvio doppia verifica...");
                result = await extractCourseDataWithDoubleCheck(
                    apiKey,
                    courseData,
                    modulesData,
                    participantsData,
                    (msg, percent) => {
                        setProgressMessage(msg);
                        setProgressPercent(percent);
                    }
                );

                // Show double check results
                if (result.metadata?.double_check) {
                    const { match_percentage, differences_count } = result.metadata.double_check;
                    const message = SUCCESS_MESSAGES.DOUBLE_CHECK_SUCCESS(match_percentage, differences_count);

                    if (match_percentage >= 95) {
                        toast.success(message.title, { description: message.description });
                    } else if (match_percentage >= 80) {
                        toast.warning(WARNING_MESSAGES.LOW_MATCH(match_percentage), {
                            description: message.description
                        });
                    } else {
                        toast.error(WARNING_MESSAGES.LOW_MATCH(match_percentage), {
                            description: WARNING_MESSAGES.VERIFY_MANUALLY
                        });
                    }
                }
            } else {
                // Standard Extraction
                setProgressMessage("Estrazione con AI in corso...");
                setProgressPercent(30);
                result = await extractCourseDataWithGemini(
                    apiKey,
                    courseData,
                    modulesData,
                    participantsData
                );
                setProgressPercent(100);
            }

            // Check for warnings
            if (result.metadata?.warnings?.length > 0) {
                toast.warning(WARNING_MESSAGES.WARNINGS_DETECTED(result.metadata.warnings.length));
            } else {
                toast.success(SUCCESS_MESSAGES.EXTRACTION_COMPLETE(result.metadata.completamento_percentuale));
            }

            onComplete(result);
        } catch (error: any) {
            console.error("Extraction error:", error);

            if (error.message.includes("429")) {
                toast.error(API_KEY_MESSAGES.QUOTA_EXCEEDED, {
                    description: API_KEY_MESSAGES.QUOTA_DESCRIPTION
                });
            } else if (error.message.includes("403") || error.message.includes("key")) {
                toast.error(API_KEY_MESSAGES.INVALID, {
                    description: API_KEY_MESSAGES.INVALID_DESCRIPTION
                });
            } else {
                toast.error(EXTRACTION_MESSAGES.GENERIC_ERROR, {
                    description: error.message || EXTRACTION_MESSAGES.RETRY_DESCRIPTION
                });
            }
        } finally {
            setIsProcessing(false);
            setProgressMessage("");
            setProgressPercent(0);
        }
    };

    return {
        // State
        currentSubStep,
        courseData,
        modulesData,
        participantsData,
        isProcessing,
        useDoubleCheck,
        progressMessage,
        progressPercent,

        // Setters (needed for inputs)
        setCourseData,
        setModulesData,
        setParticipantsData,
        setUseDoubleCheck,

        // Handlers
        handleNext,
        handleBack,
        handlePasteExample,
        handleExtraction,
    };
};

import { useEffect, useState } from "react";
