import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { FileText, Sparkles, CheckCircle, Download, LogOut, Settings, UserCheck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { toast } from "sonner";
import InputStepWizard from "@/components/steps/InputStepWizard";
import AdditionalDataStep, { AdditionalData } from "@/components/steps/AdditionalDataStep";
import CompletionStepExpanded from "@/components/steps/CompletionStepExpanded";
import GenerationStep from "@/components/steps/GenerationStep";
import SettingsDialog from "@/components/dialogs/SettingsDialog";
import { useAuth } from "@/hooks/useAuth";
import type { CourseData } from "@/types/courseData";
import { signOut } from "@/services/localAuth";

type Step = "input" | "additional" | "completion" | "generation";

// Removed unused ExtractedData interface - using CourseData from types instead

const Index = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [currentStep, setCurrentStep] = useState<Step>("input");
  const [extractedData, setExtractedData] = useState<CourseData | null>(null);
  const [additionalData, setAdditionalData] = useState<AdditionalData | null>(null);
  const [completedData, setCompletedData] = useState<any>(null);
  const [isAdmin, setIsAdmin] = useState(false);
  const [showSettingsDialog, setShowSettingsDialog] = useState(false);

  // Removed authentication requirement for main page

  useEffect(() => {
    setIsAdmin(true);
  }, [user]);

  const handleLogout = async () => {
    await signOut();
    toast.success("Logout effettuato");
    navigate("/auth");
  };

  // No loading screen needed - app is accessible without auth

  const steps = [
    { id: "input", label: "Incolla Dati", icon: FileText, completed: ["additional", "completion", "generation"].includes(currentStep) },
    { id: "additional", label: "Dati Aggiuntivi", icon: UserCheck, completed: ["completion", "generation"].includes(currentStep) },
    { id: "completion", label: "Completa Dati", icon: CheckCircle, completed: currentStep === "generation" },
    { id: "generation", label: "Genera Documenti", icon: Download, completed: false },
  ];

  const handleInputComplete = (data: CourseData) => {
    setExtractedData(data);
    setCurrentStep("additional");
  };

  const handleAdditionalComplete = (data: AdditionalData) => {
    setAdditionalData(data);

    // Merge additional data into extracted data
    if (extractedData) {
      const updatedData = {
        ...extractedData,
        trainer: {
          ...extractedData.trainer,
          nome: data.nomeDocente || extractedData.trainer?.nome,
          cognome: data.cognomeDocente || extractedData.trainer?.cognome,
          codice_fiscale: data.codiceFiscaleDocente || extractedData.trainer?.codice_fiscale,
          email: data.emailDocente || extractedData.trainer?.email,
          telefono: data.telefonoDocente || extractedData.trainer?.telefono,
          nome_completo: `${data.nomeDocente || ''} ${data.cognomeDocente || ''}`.trim() || extractedData.trainer?.nome_completo,
        },
        sede: {
          ...extractedData.sede,
          nome: data.sedeAccreditata || extractedData.sede?.nome,
          indirizzo: data.indirizzoSede || extractedData.sede?.indirizzo,
          citta: data.cittaSede || extractedData.sede?.citta,
        },
        corso: {
          ...extractedData.corso,
          id_offerta_formativa: data.idOffertaFormativa || extractedData.corso?.id_offerta_formativa,
        },
        ente: {
          ...extractedData.ente,
          nome: data.nomeEnte || extractedData.ente?.nome,
          indirizzo: data.indirizzoEnte || extractedData.ente?.indirizzo,
        },
        ente_accreditato_id: data.enteAccreditatoId || extractedData.ente_accreditato_id,

        calendario_fad: {
          ...extractedData.calendario_fad,
          strumenti: data.linkZoom || extractedData.calendario_fad?.strumenti || '',
          id_riunione: data.idRiunione,
          passcode: data.passcode,
          piattaforma: data.piattaforma || extractedData.calendario_fad?.piattaforma || '',
          modalita: extractedData.calendario_fad?.modalita || '',
          obiettivi: extractedData.calendario_fad?.obiettivi || '',
          valutazione: extractedData.calendario_fad?.valutazione || '',
          eventi: extractedData.calendario_fad?.eventi || [],
        },
        // Add note if supported
      };
      setExtractedData(updatedData);
    }

    setCurrentStep("completion");
  };

  const handleCompletionComplete = (data: any) => {
    setCompletedData(data);
    setCurrentStep("generation");
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-background to-primary/5">
      {/* Header */}
      <header className="border-b bg-card/50 backdrop-blur-sm sticky top-0 z-10">
        <div className="container mx-auto px-4 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <FileText className="h-10 w-10 text-primary" />
              <div>
                <h1 className="text-3xl font-bold tracking-tight text-foreground">
                  Compilatore Documenti di Avvio Corso
                </h1>
                <p className="text-muted-foreground">
                  Sistema Automatico di Generazione Documenti Formativi
                </p>
              </div>
            </div>
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setShowSettingsDialog(true)}>
                <Settings className="mr-2 h-4 w-4" />
                Impostazioni
              </Button>
              {user ? (
                <>
                  {isAdmin && (
                    <Button variant="outline" onClick={() => navigate("/admin")}>
                      <Settings className="mr-2 h-4 w-4" />
                      Admin
                    </Button>
                  )}
                  <Button variant="outline" onClick={handleLogout}>
                    <LogOut className="mr-2 h-4 w-4" />
                    Logout
                  </Button>
                </>
              ) : (
                <Button variant="outline" onClick={() => navigate("/auth")}>
                  Login
                </Button>
              )}
            </div>
          </div>
        </div>
      </header>

      {/* Progress Steps */}
      <div className="container mx-auto px-4 py-8">
        <Card className="p-6 shadow-lg">
          <div className="flex items-center justify-between relative">
            {/* Progress Line */}
            <div className="absolute left-0 right-0 top-6 h-0.5 bg-muted -z-10">
              <div
                className="h-full bg-gradient-to-r from-primary to-accent transition-all duration-500"
                style={{
                  width: `${(steps.findIndex(s => s.id === currentStep) / (steps.length - 1)) * 100}%`
                }}
              />
            </div>

            {steps.map((step, index) => {
              const Icon = step.icon;
              const isActive = step.id === currentStep;
              const isCompleted = step.completed;

              return (
                <div key={step.id} className="flex flex-col items-center gap-2 relative z-10">
                  <div
                    className={`
                      h-12 w-12 rounded-full flex items-center justify-center transition-all duration-300
                      ${isActive ? "bg-gradient-to-br from-primary to-accent shadow-lg scale-110" : ""}
                      ${isCompleted ? "bg-success" : ""}
                      ${!isActive && !isCompleted ? "bg-muted" : ""}
                    `}
                  >
                    <Icon className={`h-6 w-6 ${isActive || isCompleted ? "text-white" : "text-muted-foreground"}`} />
                  </div>
                  <span className={`text-sm font-medium ${isActive ? "text-primary" : "text-muted-foreground"}`}>
                    {step.label}
                  </span>
                </div>
              );
            })}
          </div>
        </Card>

        {/* Step Content */}
        <div className="mt-8">
          {currentStep === "input" && (
            <InputStepWizard onComplete={handleInputComplete} />
          )}

          {currentStep === "additional" && extractedData && (
            <AdditionalDataStep
              onComplete={handleAdditionalComplete}
              onBack={() => setCurrentStep("input")}
              initialData={{
                codiceFiscaleDocente: extractedData.trainer?.codice_fiscale,
                nomeDocente: extractedData.trainer?.nome,
                cognomeDocente: extractedData.trainer?.cognome,
                sedeAccreditata: extractedData.sede?.nome,
                indirizzoSede: extractedData.sede?.indirizzo,
                cittaSede: extractedData.sede?.citta,
                nomeEnte: extractedData.ente?.nome,
                indirizzoEnte: extractedData.ente?.indirizzo,
                piattaforma: extractedData.calendario_fad?.piattaforma,
                idOffertaFormativa: extractedData.corso?.id_offerta_formativa,
              }}
            />
          )}

          {currentStep === "completion" && extractedData && (
            <CompletionStepExpanded
              extractedData={extractedData}
              onComplete={handleCompletionComplete}
              onBack={() => setCurrentStep("additional")}
            />
          )}

          {currentStep === "generation" && completedData && (
            <GenerationStep
              data={completedData}
              onBack={() => setCurrentStep("completion")}
            />
          )}
        </div>
      </div>

      {/* Settings Dialog */}
      <SettingsDialog open={showSettingsDialog} onOpenChange={setShowSettingsDialog} />
    </div>
  );
};

export default Index;

import { localDb } from './localDb';
import { SYSTEM_INSTRUCTION, EXTRACTION_SCHEMA } from './extractionConfig';

export const CONFIG_KEYS = {
    SYSTEM_INSTRUCTION: 'system_instruction',
    EXTRACTION_SCHEMA: 'extraction_schema',
} as const;

export async function getSystemInstruction(): Promise<string> {
    try {
        const config = await localDb.system_configs.get(CONFIG_KEYS.SYSTEM_INSTRUCTION);
        return config?.value || SYSTEM_INSTRUCTION;
    } catch (error) {
        console.error('Error fetching system instruction:', error);
        return SYSTEM_INSTRUCTION;
    }
}

export async function saveSystemInstruction(instruction: string): Promise<void> {
    await localDb.system_configs.put({
        key: CONFIG_KEYS.SYSTEM_INSTRUCTION,
        value: instruction,
        updated_at: new Date().toISOString(),
    });
}

export async function getExtractionSchema(): Promise<any> {
    try {
        const config = await localDb.system_configs.get(CONFIG_KEYS.EXTRACTION_SCHEMA);
        return config?.value || EXTRACTION_SCHEMA;
    } catch (error) {
        console.error('Error fetching extraction schema:', error);
        return EXTRACTION_SCHEMA;
    }
}

export async function saveExtractionSchema(schema: any): Promise<void> {
    await localDb.system_configs.put({
        key: CONFIG_KEYS.EXTRACTION_SCHEMA,
        value: schema,
        updated_at: new Date().toISOString(),
    });
}

export async function resetToDefaults(): Promise<void> {
    await saveSystemInstruction(SYSTEM_INSTRUCTION);
    await saveExtractionSchema(EXTRACTION_SCHEMA);
}

import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';
import type { CourseData } from '@/types/courseData';

/**
 * Generates an Excel attendance register with formulas
 */
export const generateAttendanceRegister = async (data: CourseData): Promise<void> => {
  // 1. Prepare data structures
  const participants = (data.partecipanti || []).sort((a, b) => a.numero - b.numero);
  // Filter only presence sessions or use all? User said "calendario delle lezioni". 
  // Usually attendance register is for all sessions.
  const sessions = (data.sessioni || []).sort((a, b) => {
    // Sort by date/time
    const dateA = new Date(a.data_completa.split('/').reverse().join('-') + ' ' + a.ora_inizio_giornata);
    const dateB = new Date(b.data_completa.split('/').reverse().join('-') + ' ' + b.ora_inizio_giornata);
    return dateA.getTime() - dateB.getTime();
  });

  if (participants.length === 0 || sessions.length === 0) {
    console.warn('No participants or sessions to generate register');
    return;
  }

  // 2. Create Worksheet
  const wb = XLSX.utils.book_new();
  const ws_data: any[][] = [];

  // --- HEADERS (Row 1) ---
  const headers = ['Nome Corsista'];
  sessions.forEach(s => headers.push(s.data_completa)); // Dates as headers
  headers.push('Totale Ore Corsista'); // Last column
  ws_data.push(headers);

  // --- PARTICIPANT ROWS (Row 2 to N+1) ---
  // Start row index is 1 (0-based) -> Row 2 in Excel
  const startRow = 2;
  const numParticipants = participants.length;
  const endRow = startRow + numParticipants - 1; // Excel row number of last participant

  // Column indices
  const firstDateColIdx = 1; // Column B (0-based index 1)
  const lastDateColIdx = firstDateColIdx + sessions.length - 1;
  const totalColIdx = lastDateColIdx + 1;

  participants.forEach((p) => {
    const row: any[] = [p.nome_completo];
    // Empty cells for hours (or 0)
    for (let i = 0; i < sessions.length; i++) {
      row.push(''); // User will fill this
    }
    // Placeholder for total formula (will be set via cell object directly later, or we can push a dummy)
    row.push(0);
    ws_data.push(row);
  });

  // --- FOOTER ROWS ---
  // Totali Giorno (Row N+2)
  const totalDayRow: any[] = ['Totali Giorno'];
  for (let i = 0; i < sessions.length; i++) {
    totalDayRow.push(0); // Placeholder for formula
  }
  totalDayRow.push(''); // Empty for total column
  ws_data.push(totalDayRow);

  // Cumulative (Row N+3)
  const cumulativeRow: any[] = ['Ore Cumulative'];
  for (let i = 0; i < sessions.length; i++) {
    cumulativeRow.push(0); // Placeholder for formula
  }
  cumulativeRow.push(''); // Empty for total column
  ws_data.push(cumulativeRow);

  // 3. Convert to Sheet
  const ws = XLSX.utils.aoa_to_sheet(ws_data);

  // 4. ADD FORMULAS
  // Helper to get Excel cell reference (e.g., "A1", "B2")
  const encode = XLSX.utils.encode_cell;
  const encodeCol = XLSX.utils.encode_col;

  // A. Participant Totals (Column K in example)
  // For each participant row (from startRow to endRow)
  for (let i = 0; i < numParticipants; i++) {
    const rowIndex = startRow + i - 1; // 0-based index for data array, but formulas use 1-based Excel rows
    const excelRow = startRow + i; // 1-based Excel row

    // Range: FirstDateCol to LastDateCol for this row
    // e.g. SUM(B2:J2)
    const startRef = encode({ r: rowIndex + 1, c: firstDateColIdx }); // +1 because encode uses 0-based row but we want to be safe? No, encode uses 0-based.
    // Wait, XLSX.utils.encode_cell({r:0, c:0}) is "A1".
    // My participant rows in `ws_data` start at index 1 (row 2).

    const rowIdx = 1 + i; // 0-based index in sheet (Header is 0)

    const startCell = encode({ r: rowIdx, c: firstDateColIdx });
    const endCell = encode({ r: rowIdx, c: lastDateColIdx });
    const totalCellRef = encode({ r: rowIdx, c: totalColIdx });

    // Set formula
    ws[totalCellRef] = { t: 'n', f: `SUM(${startCell}:${endCell})`, v: 0 };
  }

  // B. Daily Totals (Row N+2)
  const totalDayRowIdx = 1 + numParticipants; // 0-based index for "Totali Giorno" row
  // For each date column
  for (let c = firstDateColIdx; c <= lastDateColIdx; c++) {
    const startCell = encode({ r: 1, c: c }); // First participant (Row 2)
    const endCell = encode({ r: 1 + numParticipants - 1, c: c }); // Last participant
    const targetCell = encode({ r: totalDayRowIdx, c: c });

    ws[targetCell] = { t: 'n', f: `SUM(${startCell}:${endCell})`, v: 0 };
  }

  // C. Cumulative Totals (Row N+3)
  const cumulativeRowIdx = totalDayRowIdx + 1; // 0-based index for "Ore Cumulative" row

  // First date column: Cumulative = Daily Total
  const firstDayTotalCell = encode({ r: totalDayRowIdx, c: firstDateColIdx });
  const firstCumulativeCell = encode({ r: cumulativeRowIdx, c: firstDateColIdx });
  ws[firstCumulativeCell] = { t: 'n', f: firstDayTotalCell, v: 0 };

  // Subsequent columns: Cumulative = Daily Total + Previous Cumulative
  for (let c = firstDateColIdx + 1; c <= lastDateColIdx; c++) {
    const currentDayTotalCell = encode({ r: totalDayRowIdx, c: c });
    const prevCumulativeCell = encode({ r: cumulativeRowIdx, c: c - 1 });
    const targetCell = encode({ r: cumulativeRowIdx, c: c });

    ws[targetCell] = { t: 'n', f: `${currentDayTotalCell}+${prevCumulativeCell}`, v: 0 };
  }

  // 5. Styling (Column Widths)
  const wscols = [
    { wch: 30 }, // Name column width
  ];
  // Date columns width
  for (let i = 0; i < sessions.length; i++) {
    wscols.push({ wch: 12 });
  }
  wscols.push({ wch: 15 }); // Total column
  ws['!cols'] = wscols;

  // 6. Save File
  XLSX.utils.book_append_sheet(wb, ws, 'RegistroPresenze');

  // Generate filename
  const courseTitle = data.corso?.titolo?.replace(/[^a-z0-9]/gi, '_').substring(0, 30) || 'Corso';
  const filename = `Registro_Presenze_${courseTitle}.xlsx`;

  // Write and save
  const wbout = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
  saveAs(new Blob([wbout], { type: 'application/octet-stream' }), filename);
};

