/**
 * Excel Template Generator with Clean Formatting
 *
 * Purpose: Generates Excel files with text-only formatting (no styles)
 * Implements specific business logic:
 * - Splits sessions into hourly blocks
 * - Skips lunch break (13:00-14:00)
 * - Determines TIPOLOGIA based on location
 * - Creates clean, lightweight Excel files (~11KB not 36KB)
 */

import * as XLSX from 'xlsx';
import { saveAs } from 'file-saver';
import type { ExcelColumnDefinition } from '@/types/templateConfig';

// ============================================================================
// CONSTANTS
// ============================================================================

/** Lunch break start hour (13:00) */
const LUNCH_BREAK_START_HOUR = 13;

/** Lunch break end hour (14:00) */
const LUNCH_BREAK_END_HOUR = 14;

/** Minutes per hour */
const MINUTES_PER_HOUR = 60;

/** TIPOLOGIA value for office/in-person sessions */
const TIPOLOGIA_OFFICE = '1';

/** TIPOLOGIA value for online/FAD sessions */
const TIPOLOGIA_ONLINE = '4';

/** SVOLGIMENTO value for office sessions */
const SVOLGIMENTO_OFFICE = '1';

/** SVOLGIMENTO value for online sessions */
const SVOLGIMENTO_ONLINE = '';

// ============================================================================
// TYPES
// ============================================================================

interface SessionData {
  data: string;           // DD/MM/YYYY
  ora_inizio: string;     // HH:MM
  ora_fine: string;       // HH:MM
  luogo: string;          // Location/venue
}

interface ExcelRowData {
  ID_SEZIONE: string;
  DATA_LEZIONE: string;
  TOTALE_ORE: string;
  ORA_INIZIO: string;
  ORA_FINE: string;
  TIPOLOGIA: string;
  CODICE_FISCALE_DOCENTE: string;
  MATERIA: string;
  CONTENUTI_MATERIA: string;
  SVOLGIMENTO_SEDE_LEZIONE: string;
}

// ============================================================================
// BUSINESS LOGIC - Session Processing
// ============================================================================

/**
 * Determines TIPOLOGIA and SVOLGIMENTO based on location
 *
 * Logic:
 * - If location contains "office"/"ufficio" → TIPOLOGIA=1, SVOLGIMENTO=1
 * - Otherwise (online/FAD) → TIPOLOGIA=4, SVOLGIMENTO=""
 */
function determineTipologiaAndSvolgimento(luogo: string): {
  tipologia: string;
  svolgimento: string;
} {
  const luogoLower = luogo.toLowerCase();
  const isOffice =
    luogoLower.includes('office') ||
    luogoLower.includes('ufficio') ||
    luogoLower.includes('presenza');

  return {
    tipologia: isOffice ? TIPOLOGIA_OFFICE : TIPOLOGIA_ONLINE,
    svolgimento: isOffice ? SVOLGIMENTO_OFFICE : SVOLGIMENTO_ONLINE,
  };
}

/**
 * Splits a session into hourly blocks, skipping lunch break
 *
 * Example:
 * Input: 09:00-17:00
 * Output: 7 blocks (09-10, 10-11, 11-12, 12-13, 14-15, 15-16, 16-17)
 * Note: 13:00-14:00 is SKIPPED (lunch break)
 *
 * @param oraInizio - Start time (HH:MM)
 * @param oraFine - End time (HH:MM)
 * @returns Array of hourly time blocks
 */
function splitIntoHourlyBlocks(
  oraInizio: string,
  oraFine: string
): Array<{ ora_inizio: string; ora_fine: string; durata: string }> {
  const blocks: Array<{ ora_inizio: string; ora_fine: string; durata: string }> = [];

  // Validate input
  if (!oraInizio || !oraFine) {
    console.warn('Missing start or end time');
    return blocks;
  }

  // Validate time format
  const timeRegex = /^\d{1,2}:\d{2}$/;
  if (!timeRegex.test(oraInizio) || !timeRegex.test(oraFine)) {
    console.warn('Invalid time format. Expected HH:MM');
    return blocks;
  }

  // Parse times
  const startParts = oraInizio.split(':').map(Number);
  const endParts = oraFine.split(':').map(Number);

  if (startParts.some(isNaN) || endParts.some(isNaN)) {
    console.warn('Invalid time values');
    return blocks;
  }

  const [startHour, startMin] = startParts;
  const [endHour, endMin] = endParts;

  // Validate hour/minute ranges
  if (startHour < 0 || startHour > 23 || endHour < 0 || endHour > 23 ||
      startMin < 0 || startMin > 59 || endMin < 0 || endMin > 59) {
    console.warn('Invalid hour or minute values');
    return blocks;
  }

  // Check if end time is after start time
  const startMinutes = startHour * 60 + startMin;
  const endMinutes = endHour * 60 + endMin;
  if (endMinutes <= startMinutes) {
    console.warn('End time must be after start time');
    return blocks;
  }

  // Lunch break constants (in minutes since midnight)
  const LUNCH_START = LUNCH_BREAK_START_HOUR * MINUTES_PER_HOUR; // 780 minutes (13:00)
  const LUNCH_END = LUNCH_BREAK_END_HOUR * MINUTES_PER_HOUR;     // 840 minutes (14:00)

  let currentHour = startHour;
  let currentMin = startMin;

  while (currentHour < endHour || (currentHour === endHour && currentMin < endMin)) {
    // Calculate next hour
    let nextHour = currentHour + 1;
    let nextMin = currentMin;

    // Don't exceed end time
    if (nextHour > endHour || (nextHour === endHour && nextMin > endMin)) {
      nextHour = endHour;
      nextMin = endMin;
    }

    const blockStart = `${String(currentHour).padStart(2, '0')}:${String(currentMin).padStart(2, '0')}`;
    const blockEnd = `${String(nextHour).padStart(2, '0')}:${String(nextMin).padStart(2, '0')}`;

    // Convert current block times to minutes for comparison
    const blockStartMinutes = currentHour * 60 + currentMin;
    const blockEndMinutes = nextHour * 60 + nextMin;

    // Skip if block overlaps with lunch break (13:00-14:00)
    // A block overlaps if it starts before lunch ends AND ends after lunch starts
    const overlapsLunch = blockStartMinutes < LUNCH_END && blockEndMinutes > LUNCH_START;

    if (!overlapsLunch) {
      blocks.push({
        ora_inizio: blockStart,
        ora_fine: blockEnd,
        durata: '1', // 1 hour blocks
      });
    }

    currentHour = nextHour;
    currentMin = nextMin;
  }

  return blocks;
}

/**
 * Processes sessions into Excel rows with hourly blocks
 */
export function processSessionsIntoRows(
  sessions: SessionData[],
  idSezione: string,
  codiceFiscaleDocente: string,
  materia: string
): ExcelRowData[] {
  const rows: ExcelRowData[] = [];

  // Validate inputs
  if (!sessions || !Array.isArray(sessions)) {
    console.warn('Invalid sessions array');
    return rows;
  }

  sessions.forEach((session, index) => {
    // Validate session data
    if (!session) {
      console.warn(`Session at index ${index} is null or undefined`);
      return;
    }

    if (!session.data || !session.ora_inizio || !session.ora_fine || !session.luogo) {
      console.warn(`Session at index ${index} is missing required fields`, session);
      return;
    }

    const { tipologia, svolgimento } = determineTipologiaAndSvolgimento(session.luogo);

    // Split into hourly blocks
    const blocks = splitIntoHourlyBlocks(session.ora_inizio, session.ora_fine);

    blocks.forEach((block) => {
      rows.push({
        ID_SEZIONE: idSezione || '',
        DATA_LEZIONE: session.data || '',
        TOTALE_ORE: block.durata,
        ORA_INIZIO: block.ora_inizio,
        ORA_FINE: block.ora_fine,
        TIPOLOGIA: tipologia,
        CODICE_FISCALE_DOCENTE: codiceFiscaleDocente || '',
        MATERIA: materia || '',
        CONTENUTI_MATERIA: materia || '', // Same as MATERIA as per requirements
        SVOLGIMENTO_SEDE_LEZIONE: svolgimento,
      });
    });
  });

  return rows;
}

// ============================================================================
// EXCEL GENERATION WITH CLEAN FORMATTING
// ============================================================================

/**
 * Creates a clean Excel file with text-only formatting
 *
 * Why: Default XLSX library adds styles that bloat file size (36KB)
 * This function creates minimal Excel with only text cells (~11KB)
 *
 * @param rows - Data rows to write
 * @param columns - Column definitions
 * @param filename - Output filename
 */
export function generateCleanExcel(
  rows: ExcelRowData[],
  columns: ExcelColumnDefinition[],
  filename: string
): void {
  try {
    // Create worksheet from data
    const ws = XLSX.utils.json_to_sheet(rows, {
      header: columns.map((c) => c.header),
    });

    // Force ALL cells to TEXT format
    // This prevents Excel from auto-converting strings to numbers/dates
    const range = XLSX.utils.decode_range(ws['!ref'] || 'A1');
    for (let R = range.s.r; R <= range.e.r; ++R) {
      for (let C = range.s.c; C <= range.e.c; ++C) {
        const cellRef = XLSX.utils.encode_cell({ r: R, c: C });
        if (!ws[cellRef]) continue;

        // Force string type and text format
        ws[cellRef].t = 's'; // Type: string
        ws[cellRef].z = '@'; // Format: text
      }
    }

    // Set column widths
    ws['!cols'] = columns.map((col) => ({ wch: col.width }));

    // Create workbook with minimal settings
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Registro');

    // Write with minimal options (no styles, no themes)
    const excelBuffer = XLSX.write(wb, {
      bookType: 'xlsx',
      type: 'array',
      cellStyles: false, // Disable styles
      bookSST: false,    // Disable shared string table optimization
    });

    const blob = new Blob([excelBuffer], {
      type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    });

    saveAs(blob, filename);

    console.log(`Clean Excel generated: ${filename}`);
  } catch (error: any) {
    console.error('Error generating clean Excel:', error);
    throw new Error(`Errore durante la generazione Excel: ${error.message}`);
  }
}

/**
 * Generates Excel from template-extracted data
 *
 * @param extractedData - Data extracted by AI based on template
 * @param templateConfig - Template configuration (used for column definitions)
 */
export function generateExcelFromTemplate(
  extractedData: Record<string, any>,
  templateConfig: any // TemplateConfig
): void {
  try {
    // Extract required fields
    const idSezione = extractedData.ID_SEZIONE || '';
    const codiceFiscaleDocente = extractedData.CODICE_FISCALE_DOCENTE || '';
    const materia = extractedData.MATERIA || '';
    const sessioni: SessionData[] = extractedData.SESSIONI || [];

    if (!sessioni || sessioni.length === 0) {
      throw new Error('Nessuna sessione trovata nei dati estratti');
    }

    // Process sessions into rows
    const rows = processSessionsIntoRows(
      sessioni,
      idSezione,
      codiceFiscaleDocente,
      materia
    );

    console.log(`Generated ${rows.length} rows from ${sessioni.length} sessions`);

    // Get column definitions from template config
    const columns =
      templateConfig.postProcessing?.excelColumns || getDefaultColumns();

    // Generate filename
    const filename = `Registro_Ore_${idSezione || 'NA'}_${formatDate(new Date())}.xlsx`;

    // Generate clean Excel
    generateCleanExcel(rows, columns, filename);
  } catch (error: any) {
    console.error('Error generating Excel from template:', error);
    throw error;
  }
}

/**
 * Default column definitions if not specified in template
 */
function getDefaultColumns(): ExcelColumnDefinition[] {
  return [
    { header: 'ID_SEZIONE', variableName: 'ID_SEZIONE', width: 15, format: 'text' },
    { header: 'DATA LEZIONE', variableName: 'DATA_LEZIONE', width: 12, format: 'text' },
    { header: 'TOTALE_ORE', variableName: 'TOTALE_ORE', width: 10, format: 'text' },
    { header: 'ORA_INIZIO', variableName: 'ORA_INIZIO', width: 10, format: 'text' },
    { header: 'ORA_FINE', variableName: 'ORA_FINE', width: 10, format: 'text' },
    { header: 'TIPOLOGIA', variableName: 'TIPOLOGIA', width: 10, format: 'text' },
    { header: 'CODICE FISCALE DOCENTE', variableName: 'CODICE_FISCALE_DOCENTE', width: 20, format: 'text' },
    { header: 'MATERIA', variableName: 'MATERIA', width: 30, format: 'text' },
    { header: 'CONTENUTI MATERIA', variableName: 'CONTENUTI_MATERIA', width: 30, format: 'text' },
    { header: 'SVOLGIMENTO SEDE LEZIONE', variableName: 'SVOLGIMENTO_SEDE_LEZIONE', width: 25, format: 'text' },
  ];
}

/**
 * Formats date as YYYYMMDD
 */
function formatDate(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}${month}${day}`;
}

// ============================================================================
// EXPORT UTILITY FOR BLOB CREATION (for ZIP packaging)
// ============================================================================

/**
 * Creates Excel blob without saving (for ZIP packaging)
 */
export function createCleanExcelBlob(
  rows: ExcelRowData[],
  columns: ExcelColumnDefinition[]
): Blob {
  const ws = XLSX.utils.json_to_sheet(rows, {
    header: columns.map((c) => c.header),
  });

  // Force text format on all cells
  const range = XLSX.utils.decode_range(ws['!ref'] || 'A1');
  for (let R = range.s.r; R <= range.e.r; ++R) {
    for (let C = range.s.c; C <= range.e.c; ++C) {
      const cellRef = XLSX.utils.encode_cell({ r: R, c: C });
      if (!ws[cellRef]) continue;
      ws[cellRef].t = 's';
      ws[cellRef].z = '@';
    }
  }

  ws['!cols'] = columns.map((col) => ({ wch: col.width }));

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Registro');

  const excelBuffer = XLSX.write(wb, {
    bookType: 'xlsx',
    type: 'array',
    cellStyles: false,
    bookSST: false,
  });

  return new Blob([excelBuffer], {
    type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  });
}

/**
 * FAD Multi-File Generator Service
 * 
 * Purpose: Generates separate Word documents for each FAD session day
 * Uses template: modello B FAD_placeholder.docx
 * 
 * Creates one file per FAD session with:
 * - Date (day, month, year)
 * - Lesson time (start-end)
 * - Random topic from configured list
 */

import type { CourseData } from '@/types/courseData';
import { processWordTemplate } from './wordTemplateProcessor';
import { createLocalTemplateGenerator } from './templateRegistry';
import { loadPredefinedData } from '@/utils/predefinedDataUtils';
import { extractZoomDetails } from '@/utils/stringUtils';

// ============================================================================
// CONSTANTS
// ============================================================================

const FAD_TEMPLATE_PATH = '/templates/modello B FAD_placeholder.docx';
const FAD_TEMPLATE_A_PATH = '/templates/Modello_A_FAD_template.docx';

const MONTH_NAMES = [
    'Gennaio', 'Febbraio', 'Marzo', 'Aprile', 'Maggio', 'Giugno',
    'Luglio', 'Agosto', 'Settembre', 'Ottobre', 'Novembre', 'Dicembre'
];

// ============================================================================
// MAIN FUNCTION
// ============================================================================

/**
 * Generates a single FAD registry document (Modello B) for one specific day
 * 
 * @param data - Complete course data
 * @param sessionIndex - Index of the FAD session to generate (0-based)
 * @returns Document blob ready for download/ZIP packaging
 */
export async function generateFADRegistryForDay(
    data: CourseData,
    sessionIndex: number
): Promise<Blob> {
    try {
        // 1. Get FAD sessions
        const fadSessions = (data.sessioni || []).filter(s => s.is_fad);

        if (sessionIndex < 0 || sessionIndex >= fadSessions.length) {
            throw new Error(`Invalid session index: ${sessionIndex}`);
        }

        const session = fadSessions[sessionIndex];

        // 2. Load template
        const templateResponse = await fetch(FAD_TEMPLATE_PATH);
        if (!templateResponse.ok) {
            throw new Error('Template non trovato: modello B FAD_placeholder.docx');
        }
        const templateBlob = await templateResponse.blob();

        // 3. Prepare data for this specific session
        const templateData = prepareFADSessionData(data, session);

        // 4. Process template
        const blob = await processWordTemplate({
            template: templateBlob,
            data: templateData,
            filename: `Registro_FAD_${formatDateForFilename(session.data_completa)}.docx`
        });

        return blob;
    } catch (error: any) {
        console.error('Error generating FAD registry for day:', error);
        throw new Error(`Errore generazione registro FAD: ${error.message}`);
    }
}

/**
 * Generates a single FAD Modello A document for one specific day
 * 
 * @param data - Complete course data
 * @param sessionIndex - Index of the FAD session to generate (0-based)
 * @returns Document blob ready for download/ZIP packaging
 */
export async function generateModelloAFAD(
    data: CourseData,
    sessionIndex: number
): Promise<Blob> {
    try {
        // 1. Get FAD sessions
        const fadSessions = (data.sessioni || []).filter(s => s.is_fad);

        if (sessionIndex < 0 || sessionIndex >= fadSessions.length) {
            throw new Error(`Invalid session index: ${sessionIndex}`);
        }

        const session = fadSessions[sessionIndex];

        // 2. Load template
        const templateResponse = await fetch(FAD_TEMPLATE_A_PATH);
        if (!templateResponse.ok) {
            throw new Error('Template non trovato: modello_A_FAD_con_placeholder.docx');
        }
        const templateBlob = await templateResponse.blob();

        // 3. Prepare data for this specific session
        // Assuming Modello A uses the same data structure as Modello B
        const templateData = prepareFADSessionData(data, session);

        // 4. Process template
        const blob = await processWordTemplate({
            template: templateBlob,
            data: templateData,
            filename: `Modello_A_FAD_${formatDateForFilename(session.data_completa)}.docx`
        });

        return blob;
    } catch (error: any) {
        console.error('Error generating Modello A FAD for day:', error);
        throw new Error(`Errore generazione Modello A FAD: ${error.message}`);
    }
}

/**
 * Generates ALL FAD registry documents (Modello A and Modello B) and returns them as an array
 * Used by ZIP packager to include all FAD files
 * 
 * @param data - Complete course data
 * @returns Array of {filename, blob} objects for each FAD session
 */
export async function generateAllFADRegistries(
    data: CourseData
): Promise<Array<{ filename: string; blob: Blob }>> {
    const fadSessions = (data.sessioni || []).filter(s => s.is_fad);
    const results: Array<{ filename: string; blob: Blob }> = [];

    // Generator for the single Modello A (per corso)
    const generateModelloACourse = createLocalTemplateGenerator(
        FAD_TEMPLATE_A_PATH,
        'Modello_A_FAD'
    );

    for (let i = 0; i < fadSessions.length; i++) {
        const session = fadSessions[i];

        // Generate Modello B (Registro FAD) per giornata
        try {
            const blobB = await generateFADRegistryForDay(data, i);
            const filenameB = `Registro_FAD_${formatDateForFilename(session.data_completa)}.docx`;
            results.push({ filename: filenameB, blob: blobB });
        } catch (e) {
            console.error(`Failed to generate Modello B for session ${i}`, e);
        }
    }

    // Generate a single Modello A for the whole course (ID corso)
    try {
        const blobA = await generateModelloACourse(data);
        if (blobA) {
            const filenameA = `Modello_A_FAD_${data.corso?.id || 'corso'}.docx`;
            results.push({ filename: filenameA, blob: blobA });
        }
    } catch (e) {
        console.error('Failed to generate Modello A for course', e);
    }

    return results;
}

// ============================================================================
// DATA PREPARATION
// ============================================================================

/**
 * Prepares placeholder data for a single FAD session
 */
function prepareFADSessionData(data: CourseData, session: any): Record<string, any> {
    const calculateDuration = (start: string, end: string): number => {
        try {
            const [h1, m1] = (start || '0:0').split(':').map(Number);
            const [h2, m2] = (end || '0:0').split(':').map(Number);
            return (h2 + m2 / 60) - (h1 + m1 / 60);
        } catch {
            return 0;
        }
    };

    const fadSessions = (data.sessioni || []).filter(s => s.is_fad);

    // Hours of FAD calculated on all FAD sessions
    const fadHours = fadSessions.reduce((acc, s) => {
        return acc + calculateDuration(s.ora_inizio_giornata || s.ora_inizio || '09:00', s.ora_fine_giornata || s.ora_fine || '13:00');
    }, 0);

    // Flattened topics list (argomenti) across modules
    const listaArgomenti = (data.moduli || []).flatMap(m =>
        (m.argomenti || []).map(arg => ({
            argomento: arg,
            modulo: m.titolo
        }))
    );

    // Full FAD calendar for the table section
    const sessioniFad = fadSessions.map(s => ({
        DATA: s.data_completa,
        ORA_INIZIO: s.ora_inizio_giornata || s.ora_inizio,
        ORA_FINE: s.ora_fine_giornata || s.ora_fine,
        DURATA: calculateDuration(s.ora_inizio_giornata || s.ora_inizio || '09:00', s.ora_fine_giornata || s.ora_fine || '13:00').toFixed(1).replace('.0', ''),

        // Keep lowercase for compatibility
        data: s.data_completa,
        ora_inizio: s.ora_inizio_giornata || s.ora_inizio,
        ora_fine: s.ora_fine_giornata || s.ora_fine,
        durata: calculateDuration(s.ora_inizio_giornata || s.ora_inizio || '09:00', s.ora_fine_giornata || s.ora_fine || '13:00').toFixed(1).replace('.0', '')
    }));

    // Dynamic participant placeholders (PARTECIPANTE 1, PARTECIPANTE 1 EMAIL, ...)
    // We generate placeholders for up to 20 participants to ensure empty strings for missing ones
    const partecipantiDynamic = Array.from({ length: 20 }, (_, i) => i + 1).reduce((acc, num) => {
        const p = (data.partecipanti || []).find(p => p.numero === num);

        acc[`PARTECIPANTE ${num}`] = p?.nome_completo || '';
        acc[`PARTECIPANTE ${num} EMAIL`] = p?.email || '';
        return acc;
    }, {} as Record<string, string>);

    // Extract date components
    const { giorno, mese, anno } = extractDateComponents(session.data_completa);

    // Get a random topic from configured lists
    const argomento = getRandomTopic();

    // Calculate FAD hours (duration) for this specific session
    const duration = calculateDuration(
        session.ora_inizio_giornata || session.ora_inizio || '09:00',
        session.ora_fine_giornata || session.ora_fine || '13:00'
    );

    return {
        // Date placeholders
        giorno: giorno,
        mese: mese,
        anno: anno,

        // Time placeholders
        ora_inizio: session.ora_inizio_giornata || session.ora_inizio || '09:00',
        ora_fine: session.ora_fine_giornata || session.ora_fine || '13:00',

        // Topic placeholder
        argomento_sessione: argomento,

        // Course info placeholders
        NOME_CORSO: data.corso?.titolo || 'N/A',
        ID_SEZIONE: data.corso?.id || 'N/A',
        ID_CORSO: data.corso?.id || 'N/A',

        // --- NEW MAPPINGS FOR MODELLO A ---
        ENTE_NOME: data.ente?.nome || 'N/A',
        ID_ENTE: data.ente?.id || '',
        SEDE_ACCREDITATA: data.sede?.nome || data.ente?.accreditato?.nome || 'N/A',
        ORE_FAD: duration.toFixed(1).replace('.0', ''), // Hours for this specific session/file
        NOME_DOCENTE: data.trainer?.nome_completo || 'N/A',

        // FAD Specifics
        ID_RIUNIONE: data.calendario_fad?.id_riunione || extractZoomDetails(data.calendario_fad?.strumenti || '').id || 'Da definire',
        PASSCODE: data.calendario_fad?.passcode || extractZoomDetails(data.calendario_fad?.strumenti || '').passcode || 'Da definire',
        PIATTAFORMA: data.calendario_fad?.piattaforma || data.calendario_fad?.strumenti || 'Zoom',

        // Lists
        LISTA_ARGOMENTI: (data.moduli || []).flatMap(m =>
            (m.argomenti || []).map(arg => ({
                ARGOMENTO: arg,
                MODULO: m.titolo,
                // Keep lowercase for compatibility
                argomento: arg,
                modulo: m.titolo
            }))
        ),

        // Session list (even if it's just one for this file, the template might use a loop)
        SESSIONI_FAD: [{
            DATA: session.data_completa,
            ORA_INIZIO: session.ora_inizio_giornata || session.ora_inizio || '09:00',
            ORA_FINE: session.ora_fine_giornata || session.ora_fine || '13:00',

            // Keep lowercase
            data: session.data_completa,
            ora_inizio: session.ora_inizio_giornata || session.ora_inizio || '09:00',
            ora_fine: session.ora_fine_giornata || session.ora_fine || '13:00',

            NOME_CORSO: data.corso?.titolo || 'N/A',
            NOME_DOCENTE: data.trainer?.nome_completo || 'N/A'
        }],

        // Participants table
        ...partecipantiDynamic,
    };
}



/**
 * Extracts day, month name, and year from date string
 * @param dateString - Date in format "DD/MM/YYYY" or similar
 * @returns Object with giorno, mese (name), anno
 */
function extractDateComponents(dateString: string): { giorno: string; mese: string; anno: string } {
    try {
        // Handle various date formats
        const parts = dateString.split('/');
        if (parts.length < 3) {
            throw new Error('Invalid date format');
        }

        const day = parts[0].padStart(2, '0');
        const monthIndex = parseInt(parts[1], 10) - 1; // 0-based
        const year = parts[2];

        // Get month name in Italian
        const monthName = MONTH_NAMES[monthIndex] || 'N/A';

        return {
            giorno: day,
            mese: monthName,
            anno: year
        };
    } catch (error) {
        console.error('Error extracting date components:', error);
        return {
            giorno: 'XX',
            mese: 'N/A',
            anno: '2025'
        };
    }
}

/**
 * Gets a random topic from the configured argument lists
 * Returns 'Da definire' if no lists are configured
 */
function getRandomTopic(): string {
    try {
        const predefinedData = loadPredefinedData();
        const argumentLists = predefinedData.argumentLists || [];

        // Filter only enabled lists
        const enabledLists = argumentLists.filter(list => list.enabled);

        if (enabledLists.length === 0) {
            return 'Da definire';
        }

        // Collect all topics from all enabled lists
        const allTopics: string[] = [];
        enabledLists.forEach(list => {
            if (list.arguments && list.arguments.length > 0) {
                allTopics.push(...list.arguments);
            }
        });

        if (allTopics.length === 0) {
            return 'Da definire';
        }

        // Return random topic
        const randomIndex = Math.floor(Math.random() * allTopics.length);
        return allTopics[randomIndex];
    } catch (error) {
        console.error('Error getting random topic:', error);
        return 'Da definire';
    }
}

/**
 * Formats date string for use in filename
 * Converts "22/09/2025" -> "22_09_2025"
 */
function formatDateForFilename(dateString: string): string {
    return dateString.replace(/\//g, '_');
}

