    function generateParticipantsExcelBlob(data: CourseData): Blob {
      const participantsData = (data.partecipanti || []).map((p) => ({
        'Numero': p.numero,
        'Nome': p.nome,
        'Cognome': p.cognome,
        'Nome Completo': p.nome_completo,
