  originalError?: Error;      // Original error object
  context?: Record<string, any>; // Additional context data
  timestamp: string;          // ISO timestamp
}

/**
 * Error handling options
 * Why: Allows customization of error handling behavior
 */
export interface ErrorHandlingOptions {
  showToast?: boolean;        // Show toast notification (default: true)
  logToConsole?: boolean;     // Log to console (default: true)
  rethrow?: boolean;          // Re-throw after handling (default: false)
  customMessage?: string;     // Override default message
  customDescription?: string; // Override default description
  context?: Record<string, any>; // Additional context for logging
}

// ============================================================================
// ERROR CLASSIFICATION
// ============================================================================

/**
 * Classifies an error into a category based on error message and type
 * Why: Enables appropriate error handling based on error type
 *
 * @param error - Error object or message
 * @returns ErrorCategory
 */
export function classifyError(error: Error | string): ErrorCategory {
  const errorMessage = typeof error === 'string' ? error : error.message.toLowerCase();

  // API errors
  if (errorMessage.includes('api key') || errorMessage.includes('apikey')) {
    return ErrorCategory.AUTHENTICATION;
  }
  if (errorMessage.includes('quota') || errorMessage.includes('rate limit')) {
    return ErrorCategory.API;
  }
  if (errorMessage.includes('gemini') || errorMessage.includes('api')) {
    return ErrorCategory.API;
  }

  // Network errors
  if (errorMessage.includes('network') || errorMessage.includes('timeout')) {
    return ErrorCategory.NETWORK;
  }
  if (errorMessage.includes('fetch') || errorMessage.includes('connection')) {
    return ErrorCategory.NETWORK;
  }

  // Validation errors
  if (errorMessage.includes('validation') || errorMessage.includes('invalid')) {
    return ErrorCategory.VALIDATION;
  }
  if (errorMessage.includes('required') || errorMessage.includes('missing')) {
    return ErrorCategory.VALIDATION;
  }

  // Generation errors
  if (errorMessage.includes('document') || errorMessage.includes('generation')) {
    return ErrorCategory.GENERATION;
  }
  if (errorMessage.includes('word') || errorMessage.includes('excel') || errorMessage.includes('zip')) {
    return ErrorCategory.GENERATION;
  }

  // Parsing errors
  if (errorMessage.includes('parse') || errorMessage.includes('json')) {
    return ErrorCategory.PARSING;
  }

  return ErrorCategory.UNKNOWN;
}

/**
 * Determines error severity based on category and error details
 * Why: Helps prioritize error handling and logging
 *
 * @param category - Error category
 * @param error - Error object
 * @returns ErrorSeverity
 */
export function determineSeverity(category: ErrorCategory, error: Error | string): ErrorSeverity {
  const errorMessage = typeof error === 'string' ? error : error.message.toLowerCase();

  // Fatal errors
  if (errorMessage.includes('fatal') || errorMessage.includes('critical')) {
    return ErrorSeverity.FATAL;
  }

  // High severity
  if (category === ErrorCategory.AUTHENTICATION) {
    return ErrorSeverity.HIGH;
  }
  if (errorMessage.includes('quota exceeded')) {
    return ErrorSeverity.HIGH;
  }

  // Medium severity
  if (category === ErrorCategory.API || category === ErrorCategory.NETWORK) {
    return ErrorSeverity.MEDIUM;
  }
  if (category === ErrorCategory.GENERATION) {
    return ErrorSeverity.MEDIUM;
  }

  // Low severity
  if (category === ErrorCategory.VALIDATION) {
    return ErrorSeverity.LOW;
  }

  return ErrorSeverity.MEDIUM; // Default to medium
}

// ============================================================================
// USER-FRIENDLY MESSAGE MAPPING
// ============================================================================

/**
 * Maps technical error to user-friendly Italian message
 * Why: Provides clear, actionable feedback to users
 *
 * @param error - Error object or message
 * @param category - Error category
 * @returns Object with title and description
 */
export function getUserFriendlyMessage(
  error: Error | string,
  category: ErrorCategory
): { title: string; description: string } {
  const errorMessage = typeof error === 'string' ? error : error.message.toLowerCase();

  // API Key errors
  if (errorMessage.includes('api key not found') || errorMessage.includes('missing')) {
    return {
      title: ERROR_MESSAGES.API_KEY_MISSING,
      description: ERROR_DESCRIPTIONS.API_KEY_MISSING,
    };
  }
  if (errorMessage.includes('api key') && errorMessage.includes('invalid')) {
    return {
      title: ERROR_MESSAGES.API_KEY_INVALID,
      description: ERROR_DESCRIPTIONS.API_KEY_INVALID,
    };
  }

  // Quota errors
  if (errorMessage.includes('quota')) {
    return {
      title: ERROR_MESSAGES.API_QUOTA_EXCEEDED,
      description: ERROR_DESCRIPTIONS.API_QUOTA_EXCEEDED,
    };
  }

  // Rate limit
  if (errorMessage.includes('rate limit') || errorMessage.includes('too many')) {
    return {
      title: ERROR_MESSAGES.API_RATE_LIMIT,
      description: ERROR_DESCRIPTIONS.API_RATE_LIMIT,
    };
  }

  // Network errors
  if (category === ErrorCategory.NETWORK) {
    if (errorMessage.includes('timeout')) {
      return {
        title: ERROR_MESSAGES.NETWORK_TIMEOUT,
        description: ERROR_DESCRIPTIONS.NETWORK_TIMEOUT,
      };
    }
    return {
      title: ERROR_MESSAGES.NETWORK_GENERIC,
      description: ERROR_DESCRIPTIONS.NETWORK_OFFLINE,
    };
  }

  // Validation errors
  if (category === ErrorCategory.VALIDATION) {
    if (errorMessage.includes('required')) {
      return {
        title: ERROR_MESSAGES.VALIDATION_REQUIRED,
        description: ERROR_DESCRIPTIONS.VALIDATION_REQUIRED,
      };
    }
    return {
      title: ERROR_MESSAGES.VALIDATION_INVALID,
      description: ERROR_DESCRIPTIONS.VALIDATION_INVALID,
    };
  }

  // Generation errors
  if (category === ErrorCategory.GENERATION) {
    if (errorMessage.includes('word')) {
      return {
        title: ERROR_MESSAGES.GENERATION_WORD,
        description: ERROR_DESCRIPTIONS.GENERATION_WORD,
      };
    }
    if (errorMessage.includes('excel')) {
      return {
        title: ERROR_MESSAGES.GENERATION_EXCEL,
        description: ERROR_DESCRIPTIONS.GENERATION_EXCEL,
      };
    }
    if (errorMessage.includes('zip')) {
      return {
        title: ERROR_MESSAGES.GENERATION_ZIP,
        description: ERROR_DESCRIPTIONS.GENERATION_ZIP,
      };
    }
    return {
      title: ERROR_MESSAGES.GENERATION_GENERIC,
      description: ERROR_DESCRIPTIONS.GENERIC,
    };
  }

  // Parsing errors
  if (category === ErrorCategory.PARSING) {
    if (errorMessage.includes('json')) {
      return {
        title: ERROR_MESSAGES.PARSING_JSON,
        description: ERROR_DESCRIPTIONS.PARSING_JSON,
      };
    }
    return {
      title: ERROR_MESSAGES.PARSING_DATA,
      description: ERROR_DESCRIPTIONS.PARSING_DATA,
    };
  }

  // Generic fallback
  return {
    title: ERROR_MESSAGES.GENERIC,
    description: ERROR_DESCRIPTIONS.GENERIC,
  };
}

// ============================================================================
// ERROR HANDLING FUNCTIONS
// ============================================================================

/**
 * Creates structured error information from an error object
 * Why: Standardizes error information across the application
 *
 * @param error - Error object or message
 * @param context - Additional context data
 * @returns ErrorInfo object
 */
export function createErrorInfo(
  error: Error | string,
  context?: Record<string, any>
): ErrorInfo {
  const category = classifyError(error);
  const severity = determineSeverity(category, error);
  const { title, description } = getUserFriendlyMessage(error, category);

  return {
    category,
    severity,
    message: title,
    description,
    technicalDetails: typeof error === 'string' ? error : error.message,
    originalError: typeof error === 'string' ? undefined : error,
    context,
    timestamp: new Date().toISOString(),
  };
}

/**
 * Handles an error with standardized logging and user notification
 * Why: Provides consistent error handling across the application
 *
 * @param error - Error object or message
 * @param options - Error handling options
 * @returns ErrorInfo object
 */
export function handleError(
  error: Error | string,
  options: ErrorHandlingOptions = {}
): ErrorInfo {
  const {
    showToast = true,
    logToConsole = true,
    rethrow = false,
    customMessage,
    customDescription,
    context,
  } = options;

  // Create error information
  const errorInfo = createErrorInfo(error, context);

  // Override messages if provided
  if (customMessage) errorInfo.message = customMessage;
  if (customDescription) errorInfo.description = customDescription;

  // Log to console
  if (logToConsole) {
    const logLevel = errorInfo.severity === ErrorSeverity.FATAL || errorInfo.severity === ErrorSeverity.HIGH
      ? 'error'
      : errorInfo.severity === ErrorSeverity.MEDIUM
      ? 'warn'
      : 'log';

    console[logLevel]('Error handled:', {
      category: errorInfo.category,
      severity: errorInfo.severity,
      message: errorInfo.message,
      technicalDetails: errorInfo.technicalDetails,
      context: errorInfo.context,
      timestamp: errorInfo.timestamp,
    });

    if (errorInfo.originalError && errorInfo.originalError.stack) {
      console[logLevel]('Stack trace:', errorInfo.originalError.stack);
    }
  }

  // Show toast notification
  if (showToast) {
    const toastFn = errorInfo.severity === ErrorSeverity.LOW ? toast.warning : toast.error;
    toastFn(errorInfo.message, {
      description: errorInfo.description,
      duration: 5000,
    });
  }

  // Re-throw if requested
  if (rethrow) {
    throw errorInfo.originalError || new Error(errorInfo.message);
  }

  return errorInfo;
}

/**
 * Wraps an async function with error handling
 * Why: Simplifies error handling in async operations
 *
 * Usage:
 * ```typescript
 * const safeFunction = withErrorHandling(
 *   async () => { /* your code * / },
 *   { customMessage: 'Operation failed' }
 * );
 * await safeFunction();
 * ```
 *
 * @param fn - Async function to wrap
 * @param options - Error handling options
 * @returns Wrapped function
 */
export function withErrorHandling<T>(
  fn: () => Promise<T>,
  options: ErrorHandlingOptions = {}
): () => Promise<T | null> {
  return async () => {
    try {
      return await fn();
    } catch (error: any) {
      handleError(error, options);
      return null;
    }
  };
}

/**
 * Logs an error without showing toast notification
 * Why: For errors that should be logged but not shown to user
 *
 * @param error - Error object or message
 * @param context - Additional context data
 */
export function logError(error: Error | string, context?: Record<string, any>): void {
  handleError(error, {
    showToast: false,
    logToConsole: true,
    context,
  });
}

/**
 * Shows a simple error toast without full error handling
 * Why: For simple user notifications without extensive logging
 *
 * @param message - Error message
 * @param description - Optional description
 */
export function showErrorToast(message: string, description?: string): void {
  toast.error(message, {
    description,
    duration: 5000,
  });
}

/**
 * Shows a simple warning toast
 * Why: For non-critical issues that user should be aware of
 *
 * @param message - Warning message
 * @param description - Optional description
 */
export function showWarningToast(message: string, description?: string): void {
  toast.warning(message, {
    description,
    duration: 5000,
  });
}

/**
 * Robust Helper Utilities
 *
 * Purpose: Provide safe, error-resistant helper functions
 * - Safe data access with fallbacks
 * - Retry logic for flaky operations
 * - Data sanitization and normalization
 * - Recovery strategies
 */

import { toast } from 'sonner';
import type { CourseData } from '@/types/courseData';

// ============================================================================
// CONSTANTS
// ============================================================================

/** Default maximum retry attempts for failed operations */
const DEFAULT_MAX_RETRY_ATTEMPTS = 3;

/** Default delay in milliseconds before retry */
const DEFAULT_RETRY_DELAY_MS = 1000;

/** Default backoff multiplier for exponential backoff */
const DEFAULT_BACKOFF_MULTIPLIER = 2;

// ============================================================================
// SAFE DATA ACCESS
// ============================================================================

/**
 * Safely gets nested property with fallback
 * Example: safeGet(obj, 'a.b.c', 'default')
 */
export function safeGet(obj: any, path: string, defaultValue: any = null): any {
  try {
    const keys = path.split('.');
    let current = obj;

    for (const key of keys) {
      if (current === null || current === undefined) {
        return defaultValue;
      }
      current = current[key];
    }

    return current !== undefined ? current : defaultValue;
  } catch {
    return defaultValue;
  }
}

/**
 * Safely sets nested property
 * Creates intermediate objects if needed
 */
export function safeSet(obj: any, path: string, value: any): void {
  try {
    const keys = path.split('.');
    let current = obj;

    for (let i = 0; i < keys.length - 1; i++) {
      const key = keys[i];
      if (!current[key] || typeof current[key] !== 'object') {
        current[key] = {};
      }
      current = current[key];
    }

    current[keys[keys.length - 1]] = value;
  } catch (error) {
    console.error('Error setting value:', error);
  }
}

/**
 * Safely parses JSON with fallback
 */
export function safeJSONParse<T = any>(jsonString: string, fallback: T): T {
  try {
    return JSON.parse(jsonString);
  } catch {
    console.warn('JSON parse failed, returning fallback');
    return fallback;
  }
}

/**
 * Safely stringifies with error handling
 */
export function safeJSONStringify(
  obj: any,
  pretty: boolean = false
): string {
  try {
    return JSON.stringify(obj, null, pretty ? 2 : 0);
  } catch (error) {
    console.error('JSON stringify failed:', error);
    return '{}';
  }
}

// ============================================================================
// RETRY LOGIC
// ============================================================================

interface RetryOptions {
  maxAttempts?: number;
  delayMs?: number;
  backoffMultiplier?: number;
  onRetry?: (attempt: number, error: Error) => void;
}

/**
 * Retries an async operation with exponential backoff
 */
export async function withRetry<T>(
  operation: () => Promise<T>,
  options: RetryOptions = {}
): Promise<T> {
  const {
    maxAttempts = DEFAULT_MAX_RETRY_ATTEMPTS,
    delayMs = DEFAULT_RETRY_DELAY_MS,
    backoffMultiplier = DEFAULT_BACKOFF_MULTIPLIER,
    onRetry,
  } = options;

  let lastError: Error | null = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await operation();
    } catch (error: any) {
      lastError = error;

      if (attempt === maxAttempts) {
        break;
      }

      // Calculate delay with exponential backoff
      const delay = delayMs * Math.pow(backoffMultiplier, attempt - 1);

      console.warn(
        `Attempt ${attempt} failed, retrying in ${delay}ms...`,
        error
      );

      if (onRetry) {
        onRetry(attempt, error);
      }

      await new Promise((resolve) => setTimeout(resolve, delay));
    }
  }

  throw lastError || new Error('Operation failed after retries');
}

/**
 * Retries with user feedback
 */
export async function withRetryAndToast<T>(
  operation: () => Promise<T>,
  operationName: string,
  options: RetryOptions = {}
): Promise<T> {
  return withRetry(operation, {
    ...options,
    onRetry: (attempt, error) => {
      toast.error(`${operationName} fallito (tentativo ${attempt})`, {
        description: error.message,
      });
    },
  });
}

// ============================================================================
// DATA NORMALIZATION
// ============================================================================

/**
 * Normalizes date string to DD/MM/YYYY
 */
export function normalizeDate(dateStr: string): string {
  if (!dateStr) return '';

  try {
    // Try parsing various formats
    const date = new Date(dateStr);

    if (isNaN(date.getTime())) {
      // Try DD/MM/YYYY format
      const parts = dateStr.split(/[-/]/);
      if (parts.length === 3) {
        return `${parts[0].padStart(2, '0')}/${parts[1].padStart(2, '0')}/${parts[2]}`;
      }
      return dateStr;
    }

    const day = String(date.getDate()).padStart(2, '0');
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const year = date.getFullYear();

    return `${day}/${month}/${year}`;
  } catch {
    return dateStr;
  }
}

/**
 * Normalizes time string to HH:MM
 */
export function normalizeTime(timeStr: string): string {
  if (!timeStr) return '';

  try {
    // Remove spaces and normalize separators
    const cleaned = timeStr.trim().replace(/[.:]/g, ':');

    // Extract hours and minutes
    const parts = cleaned.split(':');
    if (parts.length >= 2) {
      const hours = String(parseInt(parts[0])).padStart(2, '0');
      const minutes = String(parseInt(parts[1])).padStart(2, '0');
      return `${hours}:${minutes}`;
    }

    return timeStr;
  } catch {
    return timeStr;
  }
}

/**
 * Normalizes codice fiscale (uppercase, no spaces)
 */
export function normalizeCodiceFiscale(cf: string): string {
  if (!cf) return '';
  return cf.toUpperCase().replace(/\s/g, '');
}

/**
 * Normalizes email (lowercase, trimmed)
 */
export function normalizeEmail(email: string): string {
  if (!email) return '';
  return email.toLowerCase().trim();
}

// ============================================================================
// VALIDATION WITH FEEDBACK
// ============================================================================

/**
 * Validates and normalizes course data
 * Returns normalized data with validation warnings
 */
export function validateAndNormalizeData(data: CourseData): {
  normalizedData: CourseData;
  warnings: string[];
  errors: string[];
} {
  const warnings: string[] = [];
  const errors: string[] = [];
  const normalized = JSON.parse(JSON.stringify(data));

  // Normalize corso
  if (normalized.corso) {
    if (normalized.corso.data_inizio) {
      normalized.corso.data_inizio = normalizeDate(normalized.corso.data_inizio);
    }
    if (normalized.corso.data_fine) {
      normalized.corso.data_fine = normalizeDate(normalized.corso.data_fine);
    }

    if (!normalized.corso.id) {
      errors.push('ID Corso mancante');
    }
    if (!normalized.corso.titolo) {
      warnings.push('Titolo corso mancante');
    }
  } else {
    errors.push('Sezione "corso" mancante');
  }

  // Normalize partecipanti
  if (normalized.partecipanti && Array.isArray(normalized.partecipanti)) {
    normalized.partecipanti = normalized.partecipanti.map((p: any, idx: number) => {
      const normalizedP = { ...p };

      if (p.codice_fiscale) {
        normalizedP.codice_fiscale = normalizeCodiceFiscale(p.codice_fiscale);
      } else {
        warnings.push(`Partecipante ${idx + 1}: Codice fiscale mancante`);
      }

      if (p.email) {
        normalizedP.email = normalizeEmail(p.email);
      }

      return normalizedP;
    });
  } else {
    warnings.push('Nessun partecipante trovato');
  }

  // Normalize sessioni
  if (normalized.sessioni && Array.isArray(normalized.sessioni)) {
    normalized.sessioni = normalized.sessioni.map((s: any) => {
      const normalizedS = { ...s };

      if (s.data_completa) {
        normalizedS.data_completa = normalizeDate(s.data_completa);
      }
      if (s.ora_inizio_giornata) {
        normalizedS.ora_inizio_giornata = normalizeTime(s.ora_inizio_giornata);
      }
      if (s.ora_fine_giornata) {
        normalizedS.ora_fine_giornata = normalizeTime(s.ora_fine_giornata);
      }

      return normalizedS;
    });
  }

  return {
    normalizedData: normalized,
    warnings,
    errors,
  };
}

// ============================================================================
// ERROR RECOVERY
// ============================================================================

/**
 * Attempts to recover data from multiple sources
 */
export function recoverData(): CourseData | null {
  const sources = [
    // 1. Auto-save
    () => {
      const autoSave = localStorage.getItem('magic_form_bot_autosave');
      return autoSave ? JSON.parse(autoSave) : null;
    },
    // 2. Last export
    () => {
      const lastExport = localStorage.getItem('magic_form_bot_last_export');
      return lastExport ? JSON.parse(lastExport) : null;
    },
    // 3. Session storage
    () => {
      const session = sessionStorage.getItem('current_course_data');
      return session ? JSON.parse(session) : null;
    },
  ];

  for (const source of sources) {
    try {
      const data = source();
      if (data) {
        console.log('Data recovered from source');
        return data;
      }
    } catch (error) {
      console.warn('Recovery source failed:', error);
    }
  }

  return null;
}

/**
 * Merges partial data with defaults
 */
export function mergeWithDefaults(partial: any, defaults: any): any {
  const merged = { ...defaults };

  for (const key in partial) {
    if (partial[key] !== null && partial[key] !== undefined) {
      if (
        typeof partial[key] === 'object' &&
        !Array.isArray(partial[key]) &&
        typeof defaults[key] === 'object' &&
        !Array.isArray(defaults[key])
      ) {
        // Recursively merge objects
        merged[key] = mergeWithDefaults(partial[key], defaults[key] || {});
      } else {
        merged[key] = partial[key];
      }
    }
  }

  return merged;
}

// ============================================================================
// SAFE FILE OPERATIONS
// ============================================================================

/**
 * Safely reads file as text
 */
export async function safeReadFileAsText(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (e) => {
      resolve(e.target?.result as string);
    };

    reader.onerror = () => {
      reject(new Error('Impossibile leggere il file'));
    };

    reader.readAsText(file);
  });
}

/**
 * Validates file type and size
 */
export function validateFile(
  file: File,
  options: {
    allowedTypes?: string[];
    maxSizeMB?: number;
  } = {}
): { isValid: boolean; error?: string } {
  const { allowedTypes, maxSizeMB } = options;

  // Check file type
  if (allowedTypes && !allowedTypes.includes(file.type)) {
    return {
      isValid: false,
      error: `Tipo file non valido. Permessi: ${allowedTypes.join(', ')}`,
    };
  }

  // Check file size
  if (maxSizeMB) {
    const maxBytes = maxSizeMB * 1024 * 1024;
    if (file.size > maxBytes) {
      return {
        isValid: false,
        error: `File troppo grande (max ${maxSizeMB}MB)`,
      };
    }
  }

  return { isValid: true };
}

// ============================================================================
// DEBOUNCE & THROTTLE
// ============================================================================

/**
 * Debounces a function
 */
export function debounce<T extends (...args: any[]) => any>(
  func: T,
  waitMs: number
): (...args: Parameters<T>) => void {
  let timeout: NodeJS.Timeout | null = null;

  return function (...args: Parameters<T>) {
    if (timeout) clearTimeout(timeout);

    timeout = setTimeout(() => {
      func(...args);
    }, waitMs);
  };
}

/**
 * Throttles a function
 */
export function throttle<T extends (...args: any[]) => any>(
  func: T,
  limitMs: number
): (...args: Parameters<T>) => void {
  let inThrottle = false;

  return function (...args: Parameters<T>) {
    if (!inThrottle) {
      func(...args);
      inThrottle = true;
      setTimeout(() => {
        inThrottle = false;
      }, limitMs);
    }
  };
}

/**
 * String parsing utilities for course data
 */

/**
 * Parses capacity string in format "current/total" (e.g., "15/20")
 *
 * @param capienza - Capacity string in format "current/total"
 * @returns Object with current and total capacity numbers
 *
 * @example
 * parseCapienza("15/20") // Returns { current: 15, total: 20 }
 * parseCapienza("invalid") // Returns { current: 0, total: 0 }
 */
export function parseCapienza(capienza: string): { current: number; total: number } {
  const match = capienza.match(/(\d+)\/(\d+)/);
  if (match) {
    return {
      current: parseInt(match[1], 10),
      total: parseInt(match[2], 10),
    };
  }
  return { current: 0, total: 0 };
}

/**
 * Splits a full name into first name and last name
 * Assumes format "FirstName LastName" or "FirstName MiddleName LastName"
 *
 * @param fullName - Full name string
 * @returns Object with nome (first name) and cognome (last name)
 *
 * @example
 * splitFullName("Mario Rossi") // Returns { nome: "Mario", cognome: "Rossi" }
 * splitFullName("Maria Anna Bianchi") // Returns { nome: "Maria", cognome: "Anna Bianchi" }
 */
export function splitFullName(fullName: string): { nome: string; cognome: string } {
  const parts = (fullName || '').trim().split(' ');
  return {
    nome: parts[0] || '',
    cognome: parts.slice(1).join(' ') || '',
  };
}

/**
 * Combines first name and last name into full name
 *
 * @param nome - First name
 * @param cognome - Last name
 * @returns Full name string
 *
 * @example
 * combineFullName("Mario", "Rossi") // Returns "Mario Rossi"
 */
export function combineFullName(nome: string, cognome: string): string {
  return `${nome} ${cognome}`.trim();
}

/**
 * Extracts the city name from a location string
 * Handles formats like "City - Address", "City (Prov)", etc.
 */
export function extractCityName(location: string): string {
  if (!location) return '';

  // Normalize
  const clean = location.trim();
  if (!clean) return '';

  // Split by common separators: " - ", ", ", " ("
  // We want to find the part that is most likely the city.
  // Often format is "City - Address" or "Address, City" or "City (Prov)"

  // Strategy 1: If it contains " - ", assume "City - Address" or "Address - City"
  // But usually in this app it seems to be "City - Address" based on user request "MILANO (VARESE)" -> "MILANO"

  // Let's try splitting by non-alphanumeric separators that might delimit city/address
  const parts = clean.split(/[\-\,]/).map(p => p.trim()).filter(Boolean);

  if (parts.length === 0) return clean;

  // Return the first part. 
  // The user example "FIX ALSO {{VERBALE_LUOGO} AND LET THAT HERE SHOULD BE SAVED ONLY THE CIY (MILANO) (VARESE)"
  // implies that if the input is "MILANO (VARESE)" or "MILANO - VIA ROMA", we want "MILANO".
  // If the input is just "MILANO", we want "MILANO".

  // If there are parentheses, remove them and their content if it looks like a province?
  // User said "(MILANO) (VARESE)", maybe they meant examples of output?
  // "LET THAT HERE SHOULD BE SAVED ONLY THE CIY (MILANO) (VARESE)"
  // I interpret this as: if the value is "Milano - Via X", output "Milano".

  // Let's take the first part of split by " - " or ",".
  const firstPart = parts[0];

  // Also remove anything in parentheses if present in that first part?
  // e.g. "Milano (MI)" -> "Milano"
  return firstPart.replace(/\s*\(.*?\)\s*/g, '').trim().toUpperCase();
}

/**
 * Extracts Meeting ID and Passcode from a Zoom link
 */
export function extractZoomDetails(link: string): { id: string; passcode: string } {
  if (!link) return { id: '', passcode: '' };

  let id = '';
  let passcode = '';

  // Extract ID (usually 9-11 digits)
  // Format: /j/123456789 or /my/123456789
  const idMatch = link.match(/\/j\/(\d+)/) || link.match(/\/my\/(\d+)/) || link.match(/(\d{9,11})/);
  if (idMatch) {
    id = idMatch[1];
    // Format ID with spaces for readability (e.g. 123 456 789)
    id = id.replace(/(\d{3})(?=\d)/g, '$1 ');
  }

  // Extract Passcode (pwd=...)
  const pwdMatch = link.match(/[?&]pwd=([^&]+)/);
  if (pwdMatch) {
    passcode = pwdMatch[1];
  }

  return { id, passcode };
}

